differential_test!(
    diff_enum_with_fields,
    "DiffEnumFields",
    r#"
enum Planet {
    MERCURY(3.303e+23, 2.4397e6),
    EARTH(5.976e+24, 6.37814e6),
    JUPITER(1.9e+27, 7.1492e7);

    private final double mass;
    private final double radius;

    Planet(double mass, double radius) {
        this.mass = mass;
        this.radius = radius;
    }

    static final double G = 6.67300E-11;

    double surfaceGravity() {
        return G * mass / (radius * radius);
    }

    double surfaceWeight(double otherMass) {
        return otherMass * surfaceGravity();
    }

    @Override
    public String toString() {
        return name() + "[ordinal=" + ordinal() + "]";
    }
}

public class DiffEnumFields {
    public static void main(String[] args) {
        double earthWeight = 175;
        double mass = earthWeight / Planet.EARTH.surfaceGravity();
        for (Planet p : Planet.values()) {
            System.out.println(p + " weight: " + Math.round(p.surfaceWeight(mass)));
        }
        System.out.println(Planet.JUPITER.surfaceGravity() > Planet.EARTH.surfaceGravity());
        System.out.println(Planet.valueOf("MERCURY").ordinal());

        // Custom toString flows through switch and concat.
        Planet home = Planet.EARTH;
        switch (home) {
            case EARTH: System.out.println("home is " + home); break;
            default: System.out.println("away");
        }
    }
}
"#
);

// Constant-specific class bodies. Each constant with a `{ ... }` body becomes an
// anonymous subclass of the enum; an `abstract` method forces every constant to
// supply one and makes the enum itself abstract. Bodies also override a concrete
// method, and can mix with body-less constants.
differential_test!(
    diff_enum_constant_body,
    "DiffEnumBody",
    r#"
public class DiffEnumBody {
    // Abstract method: every constant implements it, enum is abstract.
    enum Op {
        PLUS("+") { int apply(int a, int b) { return a + b; } },
        TIMES("*") { int apply(int a, int b) { return a * b; } };
        final String glyph;
        Op(String g) { glyph = g; }
        abstract int apply(int a, int b);
    }

    // A body overrides a concrete method; one constant keeps the default.
    enum Light {
        RED { String action() { return "stop"; } },
        YELLOW,
        GREEN { String action() { return "go"; } };
        String action() { return "wait"; }
    }

    public static void main(String[] args) {
        for (Op op : Op.values()) {
            System.out.println(op + " " + op.glyph + " " + op.apply(6, 7));
        }
        System.out.println(Op.valueOf("PLUS").apply(2, 3));
        System.out.println(Op.TIMES.ordinal());

        for (Light l : Light.values()) {
            System.out.println(l + ": " + l.action());
        }
    }
}
"#
);

// javac 11: an enum with an abstract method whose constant has no body cannot
// be built (the enum is abstract, and that constant would instantiate it).
differential_wording!(
    reject_abstract_enum_missing_body,
    "RejectEnumBody",
    r"
public class RejectEnumBody {
    enum Op {
        PLUS { int apply(int a, int b) { return a + b; } },
        MINUS;
        abstract int apply(int a, int b);
    }
    public static void main(String[] args) {
        System.out.println(Op.PLUS.apply(2, 3));
    }
}
"
);

differential_test!(
    diff_varargs,
    "DiffVarargs",
    r#"
public class DiffVarargs {
    static int sum(int... numbers) {
        int total = 0;
        for (int n : numbers) total += n;
        return total;
    }

    static String join(String sep, String... parts) {
        String result = "";
        for (int i = 0; i < parts.length; i++) {
            if (i > 0) result += sep;
            result += parts[i];
        }
        return result;
    }

    static double avg(double first, double... rest) {
        double total = first;
        for (double d : rest) total += d;
        return total / (rest.length + 1);
    }

    // Overloading: a fixed-arity method wins over varargs.
    static String pick(int a, int b) { return "fixed:" + (a + b); }
    static String pick(int... xs) { return "varargs:" + xs.length; }

    public static void main(String[] args) {
        // Spread form with varying counts, including zero.
        System.out.println(sum() + " " + sum(5) + " " + sum(1, 2, 3) + " " + sum(1, 2, 3, 4, 5));

        // Passing an actual array (array form).
        int[] arr = { 10, 20, 30 };
        System.out.println(sum(arr));

        // A fixed leading parameter plus varargs.
        System.out.println(join("-", "a", "b", "c"));
        System.out.println(join(", ", "solo"));
        System.out.println(join("+") + "|");   // zero trailing args

        // Widening of trailing args to the element type.
        System.out.println(avg(2.0, 4, 6));    // ints widen to double
        System.out.println(avg(5.0));

        // Overload resolution: fixed-arity beats varargs at arity 2.
        System.out.println(pick(3, 4));
        System.out.println(pick(1));
        System.out.println(pick(1, 2, 3));

        // Varargs argument built from expressions.
        int x = 7;
        System.out.println(sum(x, x * 2, x - 1));
    }
}
"#
);

// `String.join` is the library's own varargs, modelled like `String.format`:
// its elements are a String array, a List, or individual strings — the shape
// rides in the descriptor. A null element joins as "null".
differential_test!(
    diff_string_join,
    "DiffJoin",
    r#"
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class DiffJoin {
    public static void main(String[] args) {
        String[] parts = { "a", "b", "c" };
        System.out.println(String.join(",", parts));          // array
        System.out.println(String.join("-", "x", "y", "z"));  // individual
        System.out.println(String.join("|", "solo"));         // one element
        System.out.println("[" + String.join(",") + "]");     // no elements -> empty

        List<String> list = new ArrayList<>(Arrays.asList("one", "two", "three"));
        System.out.println(String.join(" ", list));           // Iterable (List)

        System.out.println(String.join(",", "a", null, "b")); // null element -> "null"

        String[] empty = {};
        System.out.println("[" + String.join(",", empty) + "]");
    }
}
"#
);

// `assert` — a runtime no-op, because assertions are off by default on a JVM
// (only `-ea` enables them), so `java Main` neither throws nor evaluates the
// condition. The condition and the message are still type-checked, matching
// javac; here a `false` assertion does not throw and a side-effecting condition
// never runs.
differential_test!(
    diff_assert,
    "DiffAssert",
    r#"
public class DiffAssert {
    static int calls = 0;
    static boolean tick() { calls++; return false; }
    public static void main(String[] args) {
        assert 1 + 1 == 2;
        assert "a".length() == 1 : "len";
        assert false;                   // disabled: does not throw
        assert tick() : "side effect";  // disabled: never evaluated
        int x = 5;
        assert x > 0 : "x=" + x;
        System.out.println("done calls=" + calls);   // done calls=0
    }
}
"#
);

// Assignment is an expression (JLS §15.26): its value is what was stored, it is
// right-associative, and it nests in arguments and loop conditions — the idiom
// `while ((line = ...) != null)`.
differential_test!(
    diff_assignment_expression,
    "DiffAssignExpr",
    r#"
public class DiffAssignExpr {
    static class Box { int v; }
    static int n = 0;
    static String next() { n++; return n <= 3 ? "v" + n : null; }

    public static void main(String[] args) {
        int a, b, c;
        a = b = c = 5;                       // right-associative chain
        System.out.println(a + " " + b + " " + c);

        int x = 10;
        System.out.println(x += 3);          // compound expression -> 13
        System.out.println(x);

        int[] arr = new int[3];
        System.out.println(arr[1] = 99);     // array-element target
        Box box = new Box();
        System.out.println(box.v = 42);      // field target

        int sum = 0, m;
        for (int i = 0; (m = i * 2) < 6; i++) sum += m;   // assignment in a condition
        System.out.println(sum);

        String line;
        StringBuilder sb = new StringBuilder();
        while ((line = next()) != null) {    // the read-loop idiom
            sb.append(line);
        }
        System.out.println(sb);
    }
}
"#
);

// The other side of the coin: a local mutated by an assignment EXPRESSION is not
// effectively final, so a lambda capturing it is refused — as javac refuses it.
differential_wording!(
    reject_capture_mutated_by_assignment_expression,
    "RejectAssignCapture",
    r"
public class RejectAssignCapture {
    interface Task { void run(); }
    public static void main(String[] args) {
        int x = 0;
        Task t = () -> System.out.println(x);
        int y;
        y = x = 5;
        t.run();
    }
}
"
);

differential_test!(
    diff_nested_classes,
    "DiffNested",
    r#"
public class DiffNested {
    static class Node {
        int value;
        Node next;
        Node(int value) { this.value = value; }
        int reach() {
            int count = 1;
            Node n = next;
            while (n != null) { count++; n = n.next; }
            return count;
        }
    }

    static class Stack {
        private Node top;
        private int size;
        void push(int v) {
            Node node = new Node(v);
            node.next = top;
            top = node;
            size++;
        }
        int pop() {
            int v = top.value;
            top = top.next;
            size--;
            return v;
        }
        boolean isEmpty() { return top == null; }
        int size() { return size; }
    }

    enum Op { ADD, SUB, MUL }

    static int apply(Op op, int a, int b) {
        switch (op) {
            case ADD: return a + b;
            case SUB: return a - b;
            default: return a * b;
        }
    }

    public static void main(String[] args) {
        // Linked list via nested Node, chained field access.
        Node head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(3);
        head.next.next.next = new Node(4);
        System.out.println(head.value + " " + head.next.next.value + " " + head.reach());

        // Field mutation through a chain.
        head.next.value = 20;
        System.out.println(head.next.value + " " + head.next.next.value);

        // A second nested class using the first.
        Stack stack = new Stack();
        for (int i = 1; i <= 5; i++) stack.push(i * i);
        System.out.println(stack.size() + " " + stack.isEmpty());
        int sum = 0;
        while (!stack.isEmpty()) sum += stack.pop();
        System.out.println(sum + " " + stack.isEmpty());

        // Nested enum with switch.
        for (Op op : Op.values()) {
            System.out.print(op + "=" + apply(op, 6, 4) + " ");
        }
        System.out.println();

        // Qualified nested-type reference from the outer class.
        DiffNested.Node solo = new DiffNested.Node(99);
        System.out.println(solo.value + " " + solo.reach());
    }
}
"#
);

differential_test!(
    diff_interface_default_methods,
    "DiffDefault",
    r#"
interface Greeter {
    String name();
    // A default method calls an abstract method of the same interface.
    default String greet() {
        return "Hello, " + name() + "!";
    }
    default String shout() {
        return greet().toUpperCase();
    }
}

interface Describable {
    default String describe() { return "a thing"; }
}

class Person implements Greeter {
    private String who;
    Person(String who) { this.who = who; }
    public String name() { return who; }
}

class Robot implements Greeter, Describable {
    public String name() { return "R2"; }
    // Override one default, inherit the other.
    public String greet() { return "BEEP " + name(); }
}

public class DiffDefault {
    static String greetAny(Greeter g) {
        return g.greet();
    }

    public static void main(String[] args) {
        Person p = new Person("Ada");
        System.out.println(p.greet());
        System.out.println(p.shout());

        Robot r = new Robot();
        System.out.println(r.greet());     // overridden
        System.out.println(r.shout());     // inherited default, calls overridden greet
        System.out.println(r.describe());  // inherited from a second interface

        // Dispatch through an interface-typed reference.
        System.out.println(greetAny(p));
        System.out.println(greetAny(r));

        Greeter g = p;
        System.out.println(g.greet() + " / " + g.name());
    }
}
"#
);

differential_test!(
    diff_user_generics,
    "DiffGenerics",
    r#"
class Box<T> {
    private T value;
    Box(T value) { this.value = value; }
    T get() { return value; }
    void set(T value) { this.value = value; }
    boolean has() { return value != null; }
}

class Pair<A, B> {
    private final A first;
    private final B second;
    Pair(A first, B second) { this.first = first; this.second = second; }
    A first() { return first; }
    B second() { return second; }
    String show() { return "(" + first + ", " + second + ")"; }
}

class GStack<E> {
    private Node<E> top;
    private int size;
    void push(E item) {
        Node<E> node = new Node<>(item);
        node.next = top;
        top = node;
        size++;
    }
    E pop() {
        E item = top.data;
        top = top.next;
        size--;
        return item;
    }
    boolean isEmpty() { return size == 0; }
    int size() { return size; }
}

class Node<E> {
    E data;
    Node<E> next;
    Node(E data) { this.data = data; }
}

public class DiffGenerics {
    static <T> String describe(T value) {
        return value.toString();
    }

    public static void main(String[] args) {
        // Cast-free reads: box.get() yields String directly.
        Box<String> sbox = new Box<>("hi");
        String s = sbox.get();
        System.out.println(s + " " + s.length() + " " + sbox.has());
        sbox.set("bye");
        System.out.println(sbox.get().toUpperCase());

        // Multi-parameter generics are raw (reads need casts).
        Pair<String, String> pair = new Pair<>("x", "y");
        System.out.println(pair.show() + " " + (String) pair.first());

        // Generic stack: pop() yields String, no cast.
        GStack<String> stack = new GStack<>();
        stack.push("a");
        stack.push("b");
        stack.push("c");
        System.out.println(stack.size());
        String out = "";
        while (!stack.isEmpty()) out += stack.pop();
        System.out.println(out);

        // Generic method (still needs a cast on the T return).
        System.out.println(describe("text"));

        // Object top type.
        Object obj = "erased";
        System.out.println(obj + " " + obj.equals("erased"));
    }
}
"#
);

differential_test!(
    diff_autoboxing,
    "DiffBox",
    r#"
import java.util.ArrayList;

public class DiffBox {
    // Boxing across a method boundary.
    static int unwrap(Integer boxed) { return boxed; }
    static Integer wrap(int primitive) { return primitive; }

    public static void main(String[] args) {
        // Box on assignment, unbox on assignment.
        Integer i = 5;
        int x = i;
        System.out.println(i + " " + x);

        Double d = 3.5;
        double dv = d;
        System.out.println(d + " " + dv);

        Boolean flag = true;
        boolean bv = flag;
        System.out.println(flag + " " + bv);

        Character c = 'Q';
        char cv = c;
        System.out.println(c + " " + cv);

        Long bignum = 9000000000L;
        long lv = bignum;
        System.out.println(bignum + " " + lv);

        // Box to Object.
        Object o1 = 42;
        Object o2 = 2.5;
        Object o3 = true;
        System.out.println(o1 + " " + o2 + " " + o3);

        // Arithmetic auto-unboxes.
        Integer a = 10, b = 3;
        System.out.println((a + b) + " " + (a * b) + " " + (a - b) + " " + (a / b) + " " + (a % b));
        System.out.println((a > b) + " " + (a <= b) + " " + (a == 10));
        Double p = 1.5, q = 2.5;
        System.out.println((p + q) + " " + (p < q));

        // Mixed boxed/primitive arithmetic.
        Integer m = 7;
        int result = m + 3;
        double mixed = m + 0.5;
        System.out.println(result + " " + mixed);

        // Wrapper instance methods.
        Integer n = 15;
        System.out.println(n.intValue() + " " + n.doubleValue() + " " + n.compareTo(20));
        System.out.println(n.equals(15) + " " + n.equals(16) + " " + n.toString());
        System.out.println(n.hashCode());

        // Boxing through method calls.
        System.out.println(unwrap(99) + " " + wrap(7));

        // Autoboxing into a collection (already supported) plus reads.
        ArrayList<Integer> list = new ArrayList<>();
        list.add(1);
        list.add(2);
        list.add(3);
        int sum = 0;
        for (int v : list) sum += v;
        System.out.println(sum + " " + list.get(1));

        // Integer caching semantics don't matter for value use.
        Integer big1 = 1000;
        int backToPrim = big1 + 1;
        System.out.println(backToPrim);
    }
}
"#
);

// A primitive cast to `Object` performs a boxing conversion (JLS §5.5.1) —
// `(Object) i` is `(Object) Integer.valueOf(i)` — so `getClass()` reports the
// natural wrapper. It used to be rejected as an incompatible type, though the
// equivalent assignment `Object o = i;` already boxed.
differential_test!(
    diff_primitive_to_object_cast,
    "DiffObjectCast",
    r#"
import java.util.*;

public class DiffObjectCast {
    public static void main(String[] args) {
        int i = 7;
        Object o = (Object) i;
        System.out.println(o + " " + o.getClass().getName());
        System.out.println(((Object) (long) 5).getClass().getName());
        System.out.println(((Object) 3.5).getClass().getName());
        System.out.println(((Object) 'x').getClass().getName());
        System.out.println(((Object) true).getClass().getName());
        List<Object> list = new ArrayList<>();
        list.add((Object) 42);
        list.add((Object) 'z');
        System.out.println(list);
    }
}
"#
);

// A VM-raised NullPointerException in JDK 11 has a NULL detail message —
// JEP-358's helpful messages ("cannot invoke ... because ... is null") are JDK
// 14+. caturra had synthesized the JDK-14 text; every getMessage() is now null.
differential_test!(
    diff_jdk11_npe_messages,
    "DiffNpeMsg",
    r#"
public class DiffNpeMsg {
    static class P { int v; }
    public static void main(String[] args) {
        Integer x = null;
        try { int y = x; } catch (NullPointerException e) { System.out.println("unbox:" + e.getMessage()); }
        try { throw null; } catch (NullPointerException e) { System.out.println("throw:" + e.getMessage()); }
        String s = null;
        try { s.length(); } catch (NullPointerException e) { System.out.println("invoke:" + e.getMessage()); }
        int[] arr = null;
        try { int z = arr[0]; } catch (NullPointerException e) { System.out.println("index:" + e.getMessage()); }
        try { int n = arr.length; } catch (NullPointerException e) { System.out.println("length:" + e.getMessage()); }
        P p = null;
        try { int f = p.v; } catch (NullPointerException e) { System.out.println("read:" + e.getMessage()); }
        try { p.v = 3; } catch (NullPointerException e) { System.out.println("assign:" + e.getMessage()); }
    }
}
"#
);

// String.intern() returns the CANONICAL pooled reference — the one every
// literal shares — so `new String("x").intern() == "x"` is true. And
// `new String(...)` types as String (type_of mirrored the emitter), so the
// comparison compiles.
differential_test!(
    diff_string_intern_identity,
    "DiffIntern",
    r#"
public class DiffIntern {
    public static void main(String[] args) {
        String s = new String("hi").intern();
        System.out.println(s == "hi");
        System.out.println(new String("hi").intern() == "hi");
        System.out.println("HELLO".toLowerCase().intern() == "hello");
        String t = "hi";
        System.out.println(new String("hi") == t);
        System.out.println(new String("hi").equals(t));
    }
}
"#
);

// Four round-5 crashes: a method call on a bare `new Object()`; a for-each over
// a wildcard `List<?>` holding boxed ints; `Map.forEach(null)` (must throw NPE,
// not an internal error); and an inner-class FIELD initializer reading an
// enclosing instance field (the `__caturraOuter` link must be set first).
differential_test!(
    diff_round5_crashes,
    "DiffR5Crash",
    r#"
import java.util.*;
import java.util.function.BiConsumer;

public class DiffR5Crash {
    int base = 50;
    class Inner {
        int doubled = base * 2;
        int get() { return doubled; }
    }

    static void show(List<?> l) { for (Object o : l) System.out.print(o + " "); System.out.println(); }

    public static void main(String[] args) {
        Object o = new Object();
        System.out.println(o.equals(o) + " " + (o.hashCode() == o.hashCode()));
        System.out.println(o.toString().startsWith("java.lang.Object@"));
        System.out.println(o.getClass().getName());

        show(Arrays.asList(1, 2, 3));
        show(Arrays.asList("a", "b"));

        HashMap<String, Integer> m = new HashMap<>();
        m.put("a", 1);
        BiConsumer<String, Integer> f = null;
        try { m.forEach(f); System.out.println("no npe"); }
        catch (NullPointerException e) { System.out.println("NPE"); }

        System.out.println(new DiffR5Crash().new Inner().get());
    }
}
"#
);

// Varargs overload resolution picks the MOST SPECIFIC applicable method
// (JLS §15.12.2.5): `f(Integer...)`/`f(String...)` beats `f(Object...)` rather
// than being reported ambiguous, and a lone varargs method still resolves.
differential_test!(
    diff_varargs_most_specific,
    "DiffVarSpec",
    r#"
public class DiffVarSpec {
    static String f(Object... xs) { return "obj"; }
    static String f(Integer... xs) { return "int"; }
    static String g(String... xs) { return "str"; }
    static String g(Object... xs) { return "gobj"; }
    static int sum(int... xs) { int t = 0; for (int x : xs) t += x; return t; }

    public static void main(String[] args) {
        System.out.println(f(1, 2));
        System.out.println(f("x", "y"));
        System.out.println(g("a", "b"));
        System.out.println(g(1, 2));
        System.out.println(sum(1, 2, 3));
    }
}
"#
);

// Integer/Long radix API: the radix and decode overloads (toString(long,int),
// parse/valueOf(String,int), parseUnsigned*, decode), and the radix-range and
// unsigned-overflow NumberFormatException messages the JDK actually gives.
differential_test!(
    diff_integer_long_radix_api,
    "DiffRadix",
    r##"
public class DiffRadix {
    public static void main(String[] args) {
        System.out.println(Long.toString(255L, 16));
        System.out.println(Long.parseLong("ff", 16));
        System.out.println(Integer.parseUnsignedInt("ff", 16));
        System.out.println(Long.parseUnsignedLong("18446744073709551615"));
        System.out.println(Integer.valueOf("ff", 16));
        System.out.println(Long.valueOf("ff", 16));
        System.out.println(Integer.decode("0x1F"));
        System.out.println(Long.decode("#FF"));
        System.out.println(Integer.decode("-010"));
        System.out.println(Integer.parseUnsignedInt("4294967295"));

        try { Integer.parseInt("10", 40); }
        catch (NumberFormatException e) { System.out.println(e.getMessage()); }
        try { Integer.parseInt("10", 1); }
        catch (NumberFormatException e) { System.out.println(e.getMessage()); }
        try { Integer.parseUnsignedInt("4294967296"); }
        catch (NumberFormatException e) { System.out.println(e.getMessage()); }
    }
}
"##
);

// Exception semantics: a user exception subclass widens to its bundled super,
// inherits Throwable/Object methods (getClass/getLocalizedMessage/getCause),
// `initCause`/`addSuppressed`/`getSuppressed` work, and a failed cast reports
// JDK 11's module/loader clause.
differential_test!(
    diff_exception_semantics,
    "DiffExc",
    r#"
public class DiffExc {
    static class E1 extends Exception { E1(String m) { super(m); } }

    public static void main(String[] args) {
        // A user exception subclass widens to Exception / Throwable.
        Exception e = new E1("boom");
        System.out.println(e.getMessage());
        Throwable t = new E1("x");
        System.out.println(t.getMessage());

        // Inherited Throwable/Object methods on the subclass's own type.
        E1 sub = new E1("hi");
        System.out.println(sub.getClass().getSimpleName());
        System.out.println(sub.getLocalizedMessage());

        // initCause and the cause chain.
        Exception outer = new Exception("outer");
        outer.initCause(new RuntimeException("inner"));
        System.out.println(outer.getCause().getMessage());

        // addSuppressed / getSuppressed (element reached with a cast).
        Exception m = new Exception("main");
        m.addSuppressed(new RuntimeException("s1"));
        m.addSuppressed(new RuntimeException("s2"));
        Throwable[] sup = m.getSuppressed();
        System.out.println(sup.length + " " + ((Throwable) sup[0]).getMessage());

        // A failed cast: the JDK 11 module/loader parenthetical.
        Object o = "str";
        try { Integer i = (Integer) o; }
        catch (ClassCastException c) { System.out.println(c.getMessage()); }
    }
}
"#
);

// Static-initialization order (JLS §12.4). A class whose <clinit> throws is
// permanently Erroneous: the first active use throws ExceptionInInitializerError
// and every LATER one throws NoClassDefFoundError. An inherited static METHOD
// called through a subclass initializes only the DECLARING class. And an enum's
// explicit static block runs AFTER all its constants are constructed.
differential_test!(
    diff_static_init_order,
    "DiffStaticInit",
    r#"
class Boom { static int x = 1; static { if (true) throw new RuntimeException("boom"); } }
class Base { static void m() { System.out.println("m ran"); } static { System.out.println("Base init"); } }
class Sub extends Base { static { System.out.println("Sub init"); } }
enum Color {
    RED, GREEN;
    static { System.out.println("Color static block"); }
    Color() { System.out.println("ctor " + name()); }
}

public class DiffStaticInit {
    public static void main(String[] args) {
        // Failed init: EIIE first, NoClassDefFoundError after.
        try { int y = Boom.x; } catch (Throwable t) { System.out.println("1: " + t); }
        try { int y = Boom.x; } catch (Throwable t) { System.out.println("2: " + t); }

        // Inherited static method through the subclass name inits only Base.
        Sub.m();

        // The enum's static block runs after RED and GREEN are constructed.
        System.out.println("before");
        System.out.println(Color.RED);
    }
}
"#
);

// Math special cases: IEEEremainder with an infinite divisor returns the finite
// dividend (not NaN); pow with a NaN exponent is NaN (not C99's 1.0); and the
// float overloads of ulp/nextAfter answer in FLOAT precision, not double.
differential_test!(
    diff_math_special_cases,
    "DiffMathSpecial",
    r"
public class DiffMathSpecial {
    public static void main(String[] args) {
        System.out.println(Math.IEEEremainder(3.0, Double.POSITIVE_INFINITY));
        System.out.println(Math.IEEEremainder(-7.5, Double.POSITIVE_INFINITY));
        System.out.println(Math.IEEEremainder(5.3, 2.0));
        System.out.println(Math.pow(1.0, Double.NaN));
        System.out.println(Math.pow(2.0, 3.0));
        System.out.println(Math.pow(Double.NaN, 0.0));
        float u = Math.ulp(0.0f);
        System.out.println(u);
        System.out.println(Math.ulp(1.0f));
        float x = Math.nextAfter(1.0f, 2.0f);
        System.out.println(x);
        System.out.println(Math.nextAfter(1.0f, 0.0f));
        System.out.println(Math.ulp(0.0));
    }
}
"
);

// A valid interface exercising every member kind — an abstract method, a
// default method, a static method, a private helper, and a constant — still
// compiles and runs after the JLS §9.4 modifier validation was added.
differential_test!(
    diff_interface_member_kinds,
    "DiffIfaceMembers",
    r#"
interface Greeter {
    int BASE = 10;
    String name();
    default String greet() { return "hi " + name() + suffix(); }
    private String suffix() { return "!"; }
    static int base() { return BASE; }
}

public class DiffIfaceMembers {
    static class Bob implements Greeter {
        public String name() { return "bob"; }
    }
    public static void main(String[] args) {
        Greeter g = new Bob();
        System.out.println(g.greet());
        System.out.println(Greeter.base());
    }
}
"#
);

// JLS §9.4 interface-member rules, each silently accepted before.
differential_reject!(
    reject_iface_static_default,
    "RejISD",
    "interface F { static default int m() { return 1; } }\npublic class RejISD { public static void main(String[] a) {} }"
);
differential_reject!(
    reject_iface_final_default,
    "RejIFD",
    "interface F { final default int m() { return 1; } }\npublic class RejIFD { public static void main(String[] a) {} }"
);
differential_reject!(
    reject_iface_protected,
    "RejIP",
    "interface F { protected int m(); }\npublic class RejIP { public static void main(String[] a) {} }"
);
differential_reject!(
    reject_iface_default_no_body,
    "RejIDN",
    "interface F { default int m(); }\npublic class RejIDN { public static void main(String[] a) {} }"
);
differential_reject!(
    reject_iface_const_no_init,
    "RejICN",
    "interface F { int X; }\npublic class RejICN { public static void main(String[] a) {} }"
);
differential_reject!(
    reject_iface_default_overrides_object,
    "RejIDO",
    "interface F { default String toString() { return \"y\"; } }\npublic class RejIDO { public static void main(String[] a) {} }"
);

// A private interface method is not inherited (JLS §9.4): calling it on an
// implementing class is "cannot find symbol", not a method that resolves and
// crashes at run time.
differential_reject!(
    reject_private_iface_method_from_class,
    "RejPIM",
    "interface F { private int helper() { return 42; } default int m() { return helper(); } }\npublic class RejPIM { static class C implements F {}\n  public static void main(String[] a) { System.out.println(new C().helper()); } }"
);

// A class (or interface) inheriting the same default from two UNRELATED
// interfaces without overriding is an ambiguous inheritance (JLS §8.4.8).
differential_reject!(
    reject_unrelated_diamond_defaults,
    "RejDia",
    "interface A { default String x() { return \"A\"; } }\ninterface B { default String x() { return \"B\"; } }\npublic class RejDia { static class C implements A, B {}\n  public static void main(String[] z) { System.out.println(\"x\"); } }"
);

// But a RELATED override (a sub-interface's default, or the class's own) is fine.
differential_test!(
    diff_default_conflict_resolved,
    "DiffDiamondOk",
    r#"
interface A { default String x() { return "A"; } }
interface B extends A { default String x() { return "B"; } }

public class DiffDiamondOk {
    static class C implements A, B { }
    static class D implements A, B { public String x() { return "D"; } }
    public static void main(String[] args) {
        System.out.println(new C().x() + " " + new D().x());
    }
}
"#
);

// Constant-expression narrowing (JLS §5.2): a constant of type byte/short/char/
// int whose value fits assigns to a narrower byte/short/char without a cast —
// including a char literal, a constant `final` variable, and folded arithmetic.
differential_test!(
    diff_constant_narrowing,
    "DiffConstNarrow",
    r#"
public class DiffConstNarrow {
    static final int MASK = 0xFF;

    public static void main(String[] args) {
        byte b1 = 'A';
        System.out.println(b1);
        final byte x = 1, y = 2;
        byte b2 = x + y;
        System.out.println(b2);
        final int c = 65;
        char ch = c;
        System.out.println(ch);
        short s = 100 + 27;
        System.out.println(s);
        byte b3 = 10 * 12 - 5;
        System.out.println(b3);
        char c2 = 'a' + 1;
        System.out.println(c2);
        byte m = (byte) (300 & MASK);
        System.out.println(m);
        byte[] arr = {1, 'A', 10 + 20};
        System.out.println(arr[1] + " " + arr[2]);

        // A case label is range-checked against a byte/short/char selector, so
        // an IN-range label still works.
        byte sel = 100;
        switch (sel) {
            case 100: System.out.println("hit"); break;
            case 5: System.out.println("miss"); break;
        }
    }
}
"#
);

// JLS §14.11: a case label outside the byte selector's range is a lossy
// conversion — a compile error, which caturra used to silently accept.
differential_wording!(
    reject_case_label_out_of_byte_range,
    "RejectCaseByte",
    r"
public class RejectCaseByte {
    public static void main(String[] args) {
        byte b = 1;
        switch (b) {
            case 1: break;
            case 200: break;
        }
    }
}
"
);

// `Double.parseDouble`/`Float.parseFloat` accept the Java grammar Rust's parser
// rejects — a trailing type suffix (`1.0f`, `3.14d`) and the hexadecimal form
// (`0x1.8p1`) — instead of throwing; and `%a`/`%A` render the hex-float text
// `Double.toHexString` produces. Each used to abort the program.
differential_test!(
    diff_float_parse_and_hex_format,
    "DiffFloatParse",
    r#"
public class DiffFloatParse {
    public static void main(String[] args) {
        // Trailing type suffix.
        System.out.println(Double.parseDouble("1f"));
        System.out.println(Double.parseDouble("1.0d"));
        System.out.println(Double.parseDouble("3.14f"));
        System.out.println(Float.parseFloat("1.5f"));

        // Hexadecimal floating-point.
        System.out.println(Double.parseDouble("0x1.8p1"));
        System.out.println(Double.parseDouble("0x1p4"));
        System.out.println(Double.parseDouble("-0x1.0p-1"));
        System.out.println(Float.parseFloat("0x1p4"));

        // Plain forms still parse; invalid ones still throw.
        System.out.println(Double.parseDouble("  2.5  "));
        System.out.println(Double.parseDouble("NaN") + " " + Double.parseDouble("Infinity"));
        try { Double.parseDouble("0xd"); } catch (NumberFormatException e) { System.out.println("NFE"); }
        try { Double.parseDouble("abc"); } catch (NumberFormatException e) { System.out.println("NFE"); }

        // %a / %A hexadecimal-float conversion.
        System.out.println(String.format("%a", 1.0));
        System.out.println(String.format("%a", 0.5));
        System.out.println(String.format("%a", 3.0));
        System.out.println(String.format("%A", 1.0));
        System.out.println(String.format("%a", -2.5));
    }
}
"#
);

// Writing an inherited static field through the subclass name (`Sub.f = v`)
// resolves to the DECLARING class: it finds the slot (it used to abort with
// "malformed class: unknown static field") and initializes only the superclass
// that declares the field, not the subclass named (JLS §12.4.1) — matching how
// a READ of the same field already behaved.
differential_test!(
    diff_inherited_static_field_write,
    "DiffInheritedStatic",
    r#"
class Base { static int f; static { System.out.println("Base init"); } }
class Sub extends Base { static { System.out.println("Sub init"); } }

public class DiffInheritedStatic {
    public static void main(String[] args) {
        Sub.f = 10;
        System.out.println("assigned " + Sub.f);
        Sub.f += 5;
        System.out.println(Sub.f);
    }
}
"#
);

// Boolean logical operators and shifts. `&`/`|`/`^` on boxed `Boolean` unbox
// (they used to reach `IAND` on two references — a VerifyError); `&=`/`|=`/`^=`
// on a boolean are the logical compound assignments (JLS §15.26.2); and a
// compound shift's count is an independent integral operand. Each of local,
// field, static, and array targets is exercised.
differential_test!(
    diff_boolean_and_shift_operators,
    "DiffBoolShift",
    r#"
public class DiffBoolShift {
    boolean bf = true;
    int shf = 4;
    static boolean sbf = false;
    long lf = 4;
    Integer boxedShift = 8;

    public static void main(String[] args) {
        // Plain, boxed, and mixed boolean bitwise.
        boolean p = true, q = false;
        System.out.println((p & q) + " " + (p | q) + " " + (p ^ q));
        Boolean x = Boolean.TRUE, y = Boolean.FALSE;
        System.out.println((x & y) + " " + (x | y) + " " + (x ^ x));
        System.out.println(x & q);

        // Boolean compound assignment on every target kind.
        boolean r = true;
        r ^= true;
        System.out.println(r);
        r &= false;
        r |= true;
        System.out.println(r);
        DiffBoolShift o = new DiffBoolShift();
        o.bf ^= true;
        System.out.println(o.bf);
        sbf |= true;
        System.out.println(sbf);
        boolean[] ba = {true};
        ba[0] &= false;
        System.out.println(ba[0]);

        // Shift compound assignment: local, field, static-long, array, wrapper,
        // byte-narrowing, and an Integer count.
        int z = 1;
        z <<= 3;
        System.out.println(z);
        int w = 256;
        w >>= 2;
        System.out.println(w);
        int u = -8;
        u >>>= 1;
        System.out.println(u);
        o.shf <<= 3;
        System.out.println(o.shf);
        o.lf <<= 40;
        System.out.println(o.lf);
        o.boxedShift <<= 2;
        System.out.println(o.boxedShift);
        byte b = 4;
        b <<= 2;
        System.out.println(b);
        int[] ia = {2};
        ia[0] <<= 4;
        System.out.println(ia[0]);
        int v = 7;
        v <<= Integer.valueOf(2);
        System.out.println(v);
    }
}
"#
);

// A shift count must be integral (JLS §15.19), even in a compound assignment —
// `x <<= 1.5` is a COMPILE error, not the runtime VerifyError caturra produced.
differential_wording!(
    reject_compound_shift_double_count,
    "RejectShiftDouble",
    r"
public class RejectShiftDouble {
    public static void main(String[] args) {
        int x = 4;
        x <<= 1.5;
        System.out.println(x);
    }
}
"
);

// The equals/hashCode tail: each wrapper's own `hashCode` (`Boolean` is
// 1231/1237, `Long`/`Double`/`Float` fold their bits), `String.equals(Object)`
// accepts a boxed primitive, and collections compare/hash STRUCTURALLY all the
// way down — a nested `List<List<>>`, a `Set` of `List`s, a `Map` of
// collections — while an `ArrayDeque` (not a List) keeps identity equality.
differential_test!(
    diff_equals_hashcode_deep,
    "DiffEq",
    r#"
import java.util.*;

public class DiffEq {
    public static void main(String[] args) {
        // Boxed wrapper hashCode is the wrapper's own, not the raw value.
        Boolean t = true, f = false;
        System.out.println(t.hashCode() + " " + f.hashCode());
        Long l = 9000000000L;
        Double d = 3.14;
        Float fl = 1.5f;
        System.out.println(l.hashCode() + " " + d.hashCode() + " " + fl.hashCode());
        Integer i = 42;
        Character c = 'A';
        System.out.println(i.hashCode() + " " + c.hashCode());

        // String.equals(Object): a boxed primitive argument answers false.
        System.out.println("1".equals(1) + " " + "a".equals("a") + " " + "x".equals('x'));

        // Nested List<List<>> equals and hashCode.
        List<List<Integer>> a1 = new ArrayList<>();
        a1.add(Arrays.asList(1, 2));
        a1.add(Arrays.asList(3));
        List<List<Integer>> a2 = new ArrayList<>();
        a2.add(new ArrayList<>(Arrays.asList(1, 2)));
        a2.add(new ArrayList<>(Arrays.asList(3)));
        System.out.println(a1.equals(a2) + " " + (a1.hashCode() == a2.hashCode()));

        // A Map with List values, across implementations.
        Map<String, List<Integer>> m1 = new HashMap<>();
        m1.put("a", Arrays.asList(1, 2));
        Map<String, List<Integer>> m2 = new TreeMap<>();
        m2.put("a", new ArrayList<>(Arrays.asList(1, 2)));
        System.out.println(m1.equals(m2) + " " + (m1.hashCode() == m2.hashCode()));

        // A Set of Lists.
        Set<List<Integer>> s1 = new HashSet<>();
        s1.add(Arrays.asList(1, 2));
        Set<List<Integer>> s2 = new HashSet<>();
        s2.add(new ArrayList<>(Arrays.asList(1, 2)));
        System.out.println(s1.equals(s2));

        // list.contains / indexOf ask a nested list structurally.
        List<List<Integer>> ll = new ArrayList<>();
        ll.add(Arrays.asList(9, 8));
        System.out.println(ll.contains(new ArrayList<>(Arrays.asList(9, 8)))
            + " " + ll.indexOf(Arrays.asList(9, 8)));

        // Objects.equals on collections is structural too.
        System.out.println(Objects.equals(Arrays.asList(1, 2), Arrays.asList(1, 2)));

        // An ArrayDeque is NOT a List: equals stays identity.
        Deque<Integer> q1 = new ArrayDeque<>(Arrays.asList(1, 2));
        Deque<Integer> q2 = new ArrayDeque<>(Arrays.asList(1, 2));
        System.out.println(Objects.equals(q1, q2) + " " + Objects.equals(q1, q1));
    }
}
"#
);

// `new Scanner(String)` tokenizes a literal source, and `nextLine` strips a
// `\r\n` (or lone `\r`) terminator the way the JDK does — a CRLF source yields
// `a`, not `a\r`.
differential_test!(
    diff_scanner_string_source,
    "DiffScanner",
    r#"
import java.util.Scanner;

public class DiffScanner {
    public static void main(String[] args) {
        // Mixed tokens over a String source.
        Scanner sc = new Scanner("10 20 hello\nworld 3.5");
        System.out.println(sc.nextInt());
        System.out.println(sc.nextInt());
        System.out.println(sc.next());
        System.out.println(sc.next());
        System.out.println(sc.nextDouble());
        System.out.println(sc.hasNext());

        // A token then the rest of its line.
        Scanner mixed = new Scanner("42 rest of line\nsecond line\n");
        int n = mixed.nextInt();
        System.out.println(n + "|" + mixed.nextLine() + "|");
        System.out.println("[" + mixed.nextLine() + "]");
        System.out.println(mixed.hasNextLine());

        // CRLF and a lone trailing CR: the terminator is excluded.
        Scanner lines = new Scanner("a\r\nb\r\nc");
        while (lines.hasNextLine()) System.out.println("[" + lines.nextLine() + "]");
        Scanner cr = new Scanner("only\r");
        System.out.println("[" + cr.nextLine() + "]");

        // An empty source has neither a token nor a line.
        Scanner empty = new Scanner("");
        System.out.println(empty.hasNext() + " " + empty.hasNextLine());

        // Leading/trailing whitespace is skipped between tokens.
        Scanner spaced = new Scanner("  spaced   words  ");
        System.out.println("[" + spaced.next() + "][" + spaced.next() + "]");
    }
}
"#
);

// `Short` and `Byte`: `valueOf(short)`/`valueOf(byte)` box (they used to crash
// with a "not a String" ClassCastException — the compiler re-boxed the VM's
// already-boxed result), `compare` returns `x - y` (NOT the -1/0/1 sign
// `Integer.compare` gives), and the parse/range messages match the JDK's.
differential_test!(
    diff_short_byte_wrappers,
    "DiffSmallInt",
    r#"
public class DiffSmallInt {
    public static void main(String[] args) {
        // valueOf boxes — the primitive and the String forms.
        Short s = Short.valueOf((short) 5);
        Short s2 = Short.valueOf("42");
        Byte b = Byte.valueOf((byte) 3);
        Byte b2 = Byte.valueOf("7");
        System.out.println(s + " " + s2 + " " + b + " " + b2);

        // parse and the wrapper constants.
        System.out.println(Short.parseShort("100") + " " + Byte.parseByte("9"));
        System.out.println(Short.MAX_VALUE + " " + Short.MIN_VALUE
            + " " + Byte.MAX_VALUE + " " + Byte.MIN_VALUE);

        // compare returns the DIFFERENCE, not the sign.
        System.out.println(Short.compare((short) 3, (short) 5));
        System.out.println(Short.compare((short) 9, (short) 2));
        System.out.println(Byte.compare((byte) 1, (byte) 1));
        System.out.println(Byte.compare((byte) 7, (byte) 4));

        // toString, hashCode, equals, and cached identity.
        System.out.println(Short.toString((short) 8) + " " + Byte.toString((byte) 4));
        Short a = (short) 5, c = (short) 5;
        System.out.println((a == c) + " " + a.equals(c));
        System.out.println(a.intValue() + " " + a.doubleValue() + " " + a.hashCode());

        // The parse/range NumberFormatException messages.
        try { Short.parseShort("99999"); }
        catch (NumberFormatException e) { System.out.println(e.getMessage()); }
        try { Byte.parseByte("200"); }
        catch (NumberFormatException e) { System.out.println(e.getMessage()); }
        try { Short.valueOf("abc"); }
        catch (NumberFormatException e) { System.out.println(e.getMessage()); }
    }
}
"#
);

// `java.util.Objects`: the null-safe static helpers. `equals`/`hashCode`
// dispatch a user override; `hash` folds like `Arrays.hashCode`; `toString`
// renders like `String.valueOf`; `requireNonNull` returns its argument's
// inferred type and throws the JDK's NPE (with the given message or none).
differential_test!(
    diff_objects_null_safe_helpers,
    "DiffObjects",
    r#"
import java.util.Objects;

public class DiffObjects {
    static class Point {
        int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
        public boolean equals(Object o) {
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return x == p.x && y == p.y;
        }
        public int hashCode() { return Objects.hash(x, y); }
        public String toString() { return "(" + x + ", " + y + ")"; }
    }

    public static void main(String[] args) {
        // equals: null-safe, symmetric, dispatches the user override.
        System.out.println(Objects.equals("x", "x") + " " + Objects.equals("x", "y"));
        System.out.println(Objects.equals(null, null) + " " + Objects.equals("x", null)
            + " " + Objects.equals(null, "y"));
        Integer i = 5, j = 5;
        System.out.println(Objects.equals(i, j) + " " + Objects.equals(5, 6));
        Point p1 = new Point(1, 2), p2 = new Point(1, 2), p3 = new Point(3, 4);
        System.out.println(Objects.equals(p1, p2) + " " + Objects.equals(p1, p3)
            + " " + Objects.equals(p1, null));

        // hashCode: null is 0, a user object uses its override.
        System.out.println(Objects.hashCode("x") + " " + Objects.hashCode(null));
        System.out.println(Objects.hashCode(p1) + " " + (p1.hashCode() == p2.hashCode()));

        // hash: folds every argument, boxing primitives.
        System.out.println(Objects.hash(1, 2, 3));
        System.out.println(Objects.hash("a", 1, true));
        System.out.println(Objects.hash());

        // toString: null-safe, with and without a default.
        System.out.println(Objects.toString(null) + " " + Objects.toString(p1));
        System.out.println(Objects.toString(null, "default") + " " + Objects.toString("v", "d"));

        // isNull / nonNull.
        System.out.println(Objects.isNull(null) + " " + Objects.isNull("x"));
        System.out.println(Objects.nonNull(null) + " " + Objects.nonNull("x"));

        // requireNonNull: returns the argument's inferred type.
        Point r = Objects.requireNonNull(p1);
        System.out.println(r.x + " " + r);
        String s = Objects.requireNonNull("hi");
        System.out.println(s.length());
        Integer boxed = Objects.requireNonNull(7);
        System.out.println(boxed + 1);

        // requireNonNull throws the JDK's NPE — no message, then a message.
        try {
            Objects.requireNonNull(null);
        } catch (NullPointerException e) {
            System.out.println("NPE msg=" + e.getMessage());
        }
        try {
            Objects.requireNonNull(null, "was null");
        } catch (NullPointerException e) {
            System.out.println("NPE msg=" + e.getMessage());
        }
    }
}
"#
);

// A wrapper auto-unboxes (JLS §5.1.8) in every context that demands a
// primitive: an `if`/`while`/`for`/ternary CONDITION, a unary `-`/`~`/`!`, an
// array INDEX, and `++`/`--` on a wrapper local or field (which reboxes via
// valueOf, JLS §15.14.2). Each of these used to be a compile error.
differential_test!(
    diff_wrapper_unboxing_contexts,
    "DiffUnbox",
    r#"
public class DiffUnbox {
    static Integer counter = 0;
    Integer instance = 10;

    public static void main(String[] args) {
        // Boolean condition contexts.
        Boolean yes = true, no = false;
        if (yes) System.out.println("if");
        while (no) System.out.println("never");
        System.out.println(yes ? "then" : "else");
        for (Integer k = 3; k > 0; k--) System.out.print(k);
        System.out.println();

        // Unary operators on a wrapper.
        Integer i = 5;
        System.out.println(-i + " " + ~i);
        System.out.println(!no);
        long widened = -i;
        System.out.println(widened);

        // Wrapper as an array index (Integer/Character/Short/Byte).
        int[] a = {10, 20, 30};
        Integer ii = 1;
        Character ci = 2;
        Short si = 0;
        Byte bi = 1;
        System.out.println(a[ii] + " " + a[ci] + " " + a[si] + " " + a[bi]);

        // ++/-- on a wrapper local: old value for postfix, new for prefix.
        Integer p = 5;
        System.out.println(p++);
        System.out.println(p);
        System.out.println(++p);
        Long lp = 7L;
        lp--;
        System.out.println(lp);
        Integer comp = 10;
        comp += 3;
        System.out.println(comp);

        // ++/-- on a static wrapper field.
        counter++;
        System.out.println(counter);
        System.out.println(counter++);
        System.out.println(counter);

        // ++/-- on an instance wrapper field.
        DiffUnbox o = new DiffUnbox();
        o.instance--;
        System.out.println(o.instance);
        System.out.println(o.instance++);
        System.out.println(o.instance);

        // Boolean field/expression through a switch selector.
        Integer sw = 2;
        switch (sw) {
            case 1: System.out.println("one"); break;
            case 2: System.out.println("two"); break;
            default: System.out.println("other");
        }

        // A null wrapper in a condition throws NPE on unbox.
        Boolean maybe = null;
        try {
            if (maybe) System.out.println("unreached");
        } catch (NullPointerException e) {
            System.out.println("NPE");
        }
    }
}
"#
);

differential_test!(
    diff_anonymous_classes,
    "DiffAnon",
    r#"
interface Transformer {
    int transform(int value);
}

interface Describable {
    String describe();
    default String shout() { return describe().toUpperCase(); }
}

abstract class Animal {
    abstract String sound();
    String describe() { return "an animal that says " + sound(); }
}

public class DiffAnon {
    static int applyAll(Transformer t, int[] values) {
        int total = 0;
        for (int v : values) total += t.transform(v);
        return total;
    }

    public static void main(String[] args) {
        // Anonymous class implementing an interface.
        Transformer doubler = new Transformer() {
            public int transform(int value) { return value * 2; }
        };
        Transformer square = new Transformer() {
            public int transform(int value) {
                return value * value;
            }
        };
        System.out.println(doubler.transform(5) + " " + square.transform(5));

        int[] nums = { 1, 2, 3, 4 };
        System.out.println(applyAll(doubler, nums) + " " + applyAll(square, nums));

        // Anonymous class with its own field and helper method.
        Transformer counter = new Transformer() {
            private int calls = 0;
            public int transform(int value) {
                calls++;
                return value + calls;
            }
        };
        System.out.println(counter.transform(10) + " " + counter.transform(10) + " " + counter.transform(10));

        // Inherited default method through an anonymous class.
        Describable thing = new Describable() {
            public String describe() { return "a widget"; }
        };
        System.out.println(thing.describe() + " / " + thing.shout());

        // Anonymous class extending an abstract class, overriding one
        // method and inheriting another.
        Animal cat = new Animal() {
            String sound() { return "meow"; }
        };
        System.out.println(cat.sound() + " -> " + cat.describe());

        // Anonymous class in an expression used immediately.
        System.out.println(new Transformer() {
            public int transform(int v) { return -v; }
        }.transform(42));
    }
}
"#
);

differential_test!(
    diff_anonymous_capture,
    "DiffCapture",
    r#"
interface IntFn { int apply(int x); }
interface Sink { void accept(int x); }
interface Producer { String make(); }

public class DiffCapture {
    static int applyTo(IntFn f, int v) { return f.apply(v); }

    public static void main(String[] args) {
        // Capture a single effectively-final local.
        int offset = 100;
        IntFn addOffset = new IntFn() {
            public int apply(int x) { return x + offset; }
        };
        System.out.println(addOffset.apply(5) + " " + applyTo(addOffset, 20));

        // Capture several locals of mixed types.
        int base = 10;
        int scale = 3;
        String label = "result=";
        Producer p = new Producer() {
            public String make() { return label + (base * scale); }
        };
        System.out.println(p.make());

        // Capture in a loop: each anonymous instance sees its own value.
        IntFn[] fns = new IntFn[3];
        for (int i = 0; i < 3; i++) {
            final int captured = i * 10;
            fns[i] = new IntFn() {
                public int apply(int x) { return x + captured; }
            };
        }
        System.out.println(fns[0].apply(1) + " " + fns[1].apply(1) + " " + fns[2].apply(1));

        // Capture strings and an int used in a loop.
        String greeting = "hi";
        int times = 3;
        Producer repeater = new Producer() {
            public String make() {
                String out = "";
                for (int k = 0; k < times; k++) out += greeting;
                return out;
            }
        };
        System.out.println(repeater.make());

        // A captured value combined with the method's own parameter and
        // a field the anonymous class declares.
        int seed = 7;
        IntFn accumulate = new IntFn() {
            private int total = 0;
            public int apply(int x) {
                total += x + seed;
                return total;
            }
        };
        System.out.println(accumulate.apply(1) + " " + accumulate.apply(2) + " " + accumulate.apply(3));

        // Capturing an array and indexing into it.
        int[] data = { 5, 10, 15 };
        int index = 2;
        IntFn lookup = new IntFn() {
            public int apply(int x) { return data[index] + x; }
        };
        System.out.println(lookup.apply(100));
    }
}
"#
);

differential_test!(
    diff_lambdas,
    "DiffLambda",
    r#"
interface IntFn { int apply(int x); }
interface IntBiFn { int apply(int a, int b); }
interface Pred { boolean test(int x); }
interface Runner { void run(); }
interface Producer { String make(); }

public class DiffLambda {
    static int applyTo(IntFn f, int v) { return f.apply(v); }
    static int count(int[] xs, Pred p) {
        int n = 0;
        for (int x : xs) if (p.test(x)) n++;
        return n;
    }
    static IntFn compose(IntFn f, IntFn g) {
        return x -> f.apply(g.apply(x));
    }

    public static void main(String[] args) {
        // Expression and parenthesized forms.
        IntFn inc = x -> x + 1;
        IntFn sq = (x) -> x * x;
        System.out.println(inc.apply(10) + " " + sq.apply(6));

        // Multiple parameters, expression and block bodies.
        IntBiFn add = (a, b) -> a + b;
        IntBiFn max = (a, b) -> {
            if (a > b) return a;
            return b;
        };
        System.out.println(add.apply(3, 4) + " " + max.apply(9, 2));

        // Lambda as a method argument.
        System.out.println(applyTo(x -> x * 10, 5));
        int[] nums = { 1, 2, 3, 4, 5, 6 };
        System.out.println(count(nums, x -> x % 2 == 0));

        // Capturing lambdas.
        int base = 100;
        int factor = 3;
        IntFn affine = x -> x * factor + base;
        System.out.println(affine.apply(5));

        String prefix = "value: ";
        Producer p = () -> prefix + affine.apply(1);
        System.out.println(p.make());

        // Void lambda with a side effect.
        Runner r = () -> System.out.println("ran");
        r.run();

        // Lambda returned from a method (capturing its parameters).
        IntFn plusOneThenDouble = compose(x -> x * 2, x -> x + 1);
        System.out.println(plusOneThenDouble.apply(4));

        // Lambda stored in an array and called.
        IntFn[] table = new IntFn[3];
        for (int i = 0; i < 3; i++) {
            final int mult = i + 1;
            table[i] = x -> x * mult;
        }
        System.out.println(table[0].apply(10) + " " + table[1].apply(10) + " " + table[2].apply(10));

        // A lambda whose body captures and uses several things.
        int threshold = 4;
        Pred big = x -> x > threshold;
        System.out.println(big.test(5) + " " + big.test(2) + " " + count(nums, big));
    }
}
"#
);

differential_test!(
    diff_method_references,
    "DiffMethodRef",
    r#"
interface StrToInt { int apply(String s); }
interface IntBiOp { int apply(int a, int b); }
interface Factory { Box make(int v); }
interface Consumer { void accept(String s); }
interface Mapper { String apply(String s); }

class Box {
    int value;
    Box(int value) { this.value = value; }
    public String toString() { return "Box(" + value + ")"; }
    int doubled() { return value * 2; }
    static int triple(int n) { return n * 3; }
}

public class DiffMethodRef {
    static int useStrFn(StrToInt f, String s) { return f.apply(s); }

    public static void main(String[] args) {
        // Unbound instance method references.
        StrToInt len = String::length;
        System.out.println(len.apply("method") + " " + len.apply("reference"));

        Mapper upper = String::toUpperCase;
        Mapper trim = String::trim;
        System.out.println(upper.apply("hi") + "|" + trim.apply("  pad  ") + "|");

        // Static method references (library and user).
        StrToInt parse = Integer::parseInt;
        System.out.println(parse.apply("42") + " " + parse.apply("-8"));

        IntBiOp mx = Math::max;
        IntBiOp mn = Math::min;
        System.out.println(mx.apply(3, 9) + " " + mn.apply(3, 9));

        // Constructor reference.
        Factory f = Box::new;
        Box b = f.make(21);
        System.out.println(b + " " + b.doubled());

        // Bound instance method reference (on a value).
        Consumer out = System.out::println;
        out.accept("bound instance ref");

        // A method reference passed as an argument.
        System.out.println(useStrFn(String::length, "argument"));

        // Method reference used in a loop, and stored in an array.
        StrToInt[] fns = new StrToInt[2];
        fns[0] = String::length;
        fns[1] = Integer::parseInt;
        System.out.println(fns[0].apply("abcd") + " " + fns[1].apply("1000"));
    }
}
"#
);

differential_test!(
    diff_comparable,
    "DiffComparable",
    r#"
class Card implements Comparable<Card> {
    private int rank;
    public Card(int rank) { this.rank = rank; }
    public int getRank() { return rank; }
    public int compareTo(Card other) { return rank - other.rank; }
    public String toString() { return "C" + rank; }
}

interface Ranked<T> {
    int rankAgainst(T other);
}

class Player implements Ranked<Player>, Comparable<Player> {
    int score;
    Player(int score) { this.score = score; }
    public int rankAgainst(Player other) { return score - other.score; }
    public int compareTo(Player other) { return score - other.score; }
}

public class DiffComparable {
    // Selection sort over Comparable — array covariance + interface dispatch.
    static void sort(Comparable[] arr) {
        for (int i = 0; i < arr.length; i++) {
            int min = i;
            for (int j = i + 1; j < arr.length; j++) {
                if (arr[j].compareTo(arr[min]) < 0) min = j;
            }
            Comparable t = arr[min];
            arr[min] = arr[i];
            arr[i] = t;
        }
    }

    static Comparable maxOf(Comparable a, Comparable b) {
        return a.compareTo(b) >= 0 ? a : b;
    }

    public static void main(String[] args) {
        // Direct compareTo on a concrete type.
        Card a = new Card(7), b = new Card(3);
        System.out.println((a.compareTo(b) > 0) + " " + (b.compareTo(a) < 0) + " " + a.compareTo(a));

        // Sort through the Comparable interface (covariant array).
        Card[] cards = { new Card(5), new Card(2), new Card(8), new Card(1), new Card(4) };
        sort(cards);
        for (Card c : cards) System.out.print(c + " ");
        System.out.println();

        // A user generic interface implemented alongside Comparable.
        Player p = new Player(50), q = new Player(30);
        System.out.println(p.rankAgainst(q) + " " + p.compareTo(q));

        // A method taking Comparable, returning the larger.
        Card biggerCard = (Card) maxOf(a, b);
        System.out.println(biggerCard.getRank());
        Player winner = (Player) maxOf(p, q);
        System.out.println(winner.score);

        // Sort players too.
        Player[] players = { new Player(40), new Player(10), new Player(70), new Player(20) };
        sort(players);
        for (Player pl : players) System.out.print(pl.score + " ");
        System.out.println();
    }
}
"#
);

differential_test!(
    diff_codeorg_console_patterns,
    "DiffCodeorg",
    r#"
// Patterns drawn from the Code.org CSA console curriculum.

// A user class named Character shadows java.lang.Character.
class Character {
    String name;
    boolean hero;
    Character(String name, boolean hero) { this.name = name; this.hero = hero; }
    public String toString() { return name + (hero ? "(hero)" : "(villain)"); }
}

class FoodTruck {
    public static String businessName = "Project Mercury Pastries";
    private String owner;
    FoodTruck(String owner) { this.owner = owner; }
    public String getOwner() { return owner; }
}

class Account {
    protected double balance;
    Account(double b) { balance = b; }
    void withdraw(double amount) { balance -= amount; }
}

class BasicAccount extends Account {
    BasicAccount(double b) { super(b); }
    void withdraw(double amount) {
        // super.method() as a statement.
        super.withdraw(amount);
        System.out.println("Withdrew " + amount);
    }
}

public class DiffCodeorg {
    public static void main(String[] args) {
        // Leading-dot double literals.
        double tax = .1;
        double discount = .25;
        double total = 100 * (1 + tax) - .5;
        System.out.println(tax + " " + discount + " " + total);

        // Wrapper constructors (deprecated but taught).
        Integer i = new Integer(42);
        Double d = new Double(3.14);
        Integer parsed = new Integer("100");
        System.out.println(i + " " + d + " " + parsed + " " + (i + parsed));

        // ArrayList of a user-defined Character type.
        java.util.ArrayList<Character> cast = new java.util.ArrayList<Character>();
        cast.add(new Character("Mario", true));
        cast.add(new Character("Bowser", false));
        for (Character c : cast) System.out.print(c + " ");
        System.out.println();

        // Static field access and assignment through an instance.
        FoodTruck rosies = new FoodTruck("Rosie");
        FoodTruck erins = new FoodTruck("Erin");
        System.out.println(rosies.getOwner() + ": " + rosies.businessName);
        rosies.businessName = "The Neighborhood Food Truck";
        System.out.println(erins.getOwner() + ": " + erins.businessName);
        System.out.println(FoodTruck.businessName);

        // super.method() as a statement.
        BasicAccount acct = new BasicAccount(100.0);
        acct.withdraw(30.0);
        System.out.println(acct.balance);
    }
}
"#
);

