differential_test!(
    diff_lambda_captures_enclosing_instance,
    "DiffLambdaInstance",
    r#"
interface IntFn { int go(); }
interface Run { void go(); }

public class DiffLambdaInstance {
    int field = 100;
    static int stat = 7;

    int bump() { return field + 5; }

    // Every way a lambda reaches the enclosing instance.
    IntFn bareRead() { return () -> field; }
    IntFn thisRead() { return () -> this.f2(); }
    int f2() { return field * 2; }
    IntFn callMethod() { return () -> bump(); }
    Run write() { return () -> { field = field + 10; }; }
    IntFn asValue() { return () -> { DiffLambdaInstance self = this; return self.field; }; }

    // Mixed with a local, a parameter, and a static field.
    int mixed(int param) {
        int local = 3;
        IntFn a = () -> field + local + param + stat;
        return a.go();
    }

    // A parameter shadowing the field: the lambda means the parameter.
    int shadowed(int field) {
        IntFn a = () -> field;
        return a.go();
    }

    public static void main(String[] args) {
        DiffLambdaInstance it = new DiffLambdaInstance();
        System.out.println(it.bareRead().go());
        System.out.println(it.thisRead().go());
        System.out.println(it.callMethod().go());
        it.write().go();
        System.out.println(it.field);
        System.out.println(it.asValue().go());
        it.write().go();
        System.out.println(it.field);
        System.out.println(it.mixed(10));
        System.out.println(it.shadowed(42));

        // Two objects: each lambda sees its own object's field, live.
        DiffLambdaInstance a = new DiffLambdaInstance();
        DiffLambdaInstance b = new DiffLambdaInstance();
        a.field = 1;
        b.field = 2;
        Run ra = a.write();
        Run rb = b.write();
        ra.go();
        rb.go();
        System.out.println(a.field + " " + b.field);
    }
}
"#
);

differential_test!(
    diff_lambda_as_a_list_element,
    "DiffLambdaListElement",
    r"
import java.util.ArrayList;
import java.util.List;

interface IntFn { int go(); }

public class DiffLambdaListElement {
    static List<IntFn> makeList() {
        List<IntFn> l = new ArrayList<IntFn>();
        l.add(() -> 42);
        return l;
    }

    public static void main(String[] args) {
        ArrayList<IntFn> l = new ArrayList<IntFn>();
        l.add(() -> 7);            // add(E)
        l.add(() -> 8);
        l.add(1, () -> 9);         // add(int, E)
        l.set(0, () -> 5);         // set(int, E)
        int sum = 0;
        for (int i = 0; i < l.size(); i++) {
            sum += l.get(i).go();
        }
        System.out.println(sum);

        // A lambda element that captures a local.
        int base = 100;
        List<IntFn> m = new ArrayList<IntFn>();
        m.add(() -> base + 1);
        System.out.println(m.get(0).go());

        // A method returning a List, whose body adds a lambda element.
        System.out.println(makeList().get(0).go());

        // A method reference as the element, too.
        List<IntFn> refs = new ArrayList<IntFn>();
        refs.add(DiffLambdaListElement::seven);
        System.out.println(refs.get(0).go());
    }

    static int seven() {
        return 7;
    }
}
"
);

differential_test!(
    diff_array_downcast,
    "DiffArrayDowncast",
    r#"
public class DiffArrayDowncast {
    public static void main(String[] args) {
        // `(T[]) obj` parses and casts back to the exact array type.
        Object oi = new int[] {1, 2, 3};
        int[] i = (int[]) oi;
        System.out.println(i[2]);

        Object os = new String[] {"x", "y"};
        String[] s = (String[]) os;
        System.out.println(s[1]);

        Object og = new int[2][3];
        int[][] g = (int[][]) og;
        System.out.println(g.length + " " + g[0].length);

        Object od = new double[] {1.5};
        System.out.println(((double[]) od)[0]);

        // `(int[]) null` is null.
        Object on = null;
        int[] n = (int[]) on;
        System.out.println(n == null);

        // Covariance and its limits, all at run time.
        Object anInt = new int[] {1};
        Object aStr = new String[] {"a"};
        Object nested = new int[2][2];
        Object plain = "hello";
        report("wrongElem", () -> { String[] x = (String[]) anInt; });
        report("nonArray", () -> { int[] x = (int[]) plain; });
        report("primInvariant", () -> { long[] x = (long[]) anInt; });
        report("refToObjectArr", () -> { Object[] o = (Object[]) aStr; });
        report("primToObjectArr", () -> { Object[] o = (Object[]) anInt; });
        report("nestedToObjectArr", () -> { Object[] o = (Object[]) nested; });
    }

    interface Attempt { void run(); }

    static void report(String label, Attempt a) {
        try {
            a.run();
            System.out.println(label + ": ok");
        } catch (ClassCastException e) {
            System.out.println(label + ": CCE");
        }
    }
}
"#
);

differential_test!(
    diff_list_for_each_and_remove_if,
    "DiffListForEach",
    r#"
import java.util.ArrayList;
import java.util.List;

public class DiffListForEach {
    public static void main(String[] args) {
        ArrayList<String> words = new ArrayList<String>();
        words.add("apple");
        words.add("berry");
        words.add("cherry");
        words.forEach(s -> System.out.println(s.toUpperCase()));

        List<Integer> nums = new ArrayList<Integer>();
        for (int i = 1; i <= 5; i++) nums.add(i);

        // A block body mutating a captured array.
        int[] total = {0};
        nums.forEach(n -> { total[0] += n; });
        System.out.println("sum=" + total[0]);

        // removeIf returns whether anything went, and mutates in place.
        int limit = 3;
        System.out.println(nums.removeIf(n -> n > limit));
        System.out.println(nums);
        System.out.println(nums.removeIf(n -> n > 100));
        System.out.println(nums);

        // Empty list: forEach calls nothing, removeIf removes nothing.
        List<String> empty = new ArrayList<String>();
        empty.forEach(s -> System.out.println("never"));
        System.out.println(empty.removeIf(s -> true));
    }
}
"#
);

differential_test!(
    diff_list_replace_all,
    "DiffReplaceAll",
    r#"
import java.util.ArrayList;
import java.util.List;

public class DiffReplaceAll {
    public static void main(String[] args) {
        ArrayList<Integer> nums = new ArrayList<Integer>();
        nums.add(1);
        nums.add(2);
        nums.add(3);
        int factor = 10;
        nums.replaceAll(n -> n * factor);   // primitive result, captured factor
        System.out.println(nums);
        int sum = 0;
        for (int i = 0; i < nums.size(); i++) sum += nums.get(i);
        System.out.println(sum);

        ArrayList<String> words = new ArrayList<String>();
        words.add("a");
        words.add("bb");
        words.replaceAll(s -> s.toUpperCase() + s.length());   // reference result
        System.out.println(words);

        List<Double> ds = new ArrayList<Double>();
        ds.add(1.5);
        ds.add(2.5);
        ds.replaceAll(x -> x + 0.5);
        System.out.println(ds);

        // A block body with a nested return.
        ArrayList<Integer> b = new ArrayList<Integer>();
        b.add(1);
        b.add(5);
        b.replaceAll(n -> {
            if (n > 3) {
                return n;
            }
            return 0;
        });
        System.out.println(b);

        // Empty list.
        ArrayList<Integer> e = new ArrayList<Integer>();
        e.replaceAll(x -> x + 1);
        System.out.println(e);
    }
}
"#
);

differential_test!(
    diff_sort_with_comparator,
    "DiffSortComparator",
    r#"
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Rec {
    String name;
    int n;
    Rec(String name, int n) { this.name = name; this.n = n; }
    public String toString() { return name + n; }
}

public class DiffSortComparator {
    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<Integer>();
        nums.add(3);
        nums.add(1);
        nums.add(2);
        nums.sort((x, y) -> x - y);
        System.out.println(nums);
        nums.sort((x, y) -> y - x);
        System.out.println(nums);

        // Captured direction.
        int dir = -1;
        nums.sort((x, y) -> dir * (x - y));
        System.out.println(nums);

        // Collections.sort(list, comparator) — the two-argument form.
        List<String> words = new ArrayList<String>();
        words.add("ccc");
        words.add("a");
        words.add("bb");
        Collections.sort(words, (x, y) -> x.length() - y.length());
        System.out.println(words);

        // Stability: equal keys keep input order.
        List<Rec> recs = new ArrayList<Rec>();
        recs.add(new Rec("B", 2));
        recs.add(new Rec("A", 1));
        recs.add(new Rec("C", 2));
        recs.sort((x, y) -> x.n - y.n);
        System.out.println(recs);

        // A block-body comparator.
        recs.sort((x, y) -> {
            return x.name.compareTo(y.name);
        });
        System.out.println(recs);

        // Empty.
        List<Integer> empty = new ArrayList<Integer>();
        empty.sort((x, y) -> x - y);
        System.out.println(empty);
    }
}
"#
);

differential_test!(
    diff_lambda_statement_expression_body,
    "DiffLambdaStmtBody",
    r#"
import java.util.ArrayList;
import java.util.List;

interface Run {
    void go();
}

public class DiffLambdaStmtBody {
    static int counter = 0;

    public static void main(String[] args) {
        // Assignment to an array element as a lambda body (`forEach` idiom).
        int[] sum = {0};
        List<Integer> nums = new ArrayList<Integer>();
        for (int i = 1; i <= 5; i++) nums.add(i);
        nums.forEach(n -> sum[0] += n);
        System.out.println(sum[0]);

        // Postfix increment as a lambda body.
        Run inc = () -> counter++;
        inc.go();
        inc.go();
        System.out.println(counter);

        // Prefix increment.
        Run pre = () -> ++counter;
        pre.go();
        System.out.println(counter);

        // Plain assignment.
        Run set = () -> counter = 100;
        set.go();
        System.out.println(counter);

        // A value expression body still works.
        List<String> words = new ArrayList<String>();
        words.add("a");
        words.add("bb");
        words.replaceAll(x -> x + x.length());
        System.out.println(words);
    }
}
"#
);

