differential_test!(
    diff_stream_pipeline,
    "DiffStream",
    r#"
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

public class DiffStream {
    static class Person {
        String name;
        int age;
        Person(String n, int a) { name = n; age = a; }
    }

    public static void main(String[] args) {
        List<Person> people = new ArrayList<>();
        people.add(new Person("Carol", 30));
        people.add(new Person("Alice", 25));
        people.add(new Person("Bob", 35));

        // filter -> map -> collect
        List<String> adults = people.stream()
            .filter(p -> p.age >= 30)
            .map(p -> p.name)
            .collect(Collectors.toList());
        System.out.println(adults);                 // [Carol, Bob]

        // map -> sorted -> collect
        List<String> names = people.stream()
            .map(p -> p.name)
            .sorted()
            .collect(Collectors.toList());
        System.out.println(names);                  // [Alice, Bob, Carol]

        System.out.println(people.stream().filter(p -> p.age > 28).count());
        System.out.println(people.stream().anyMatch(p -> p.age > 34));
        System.out.println(people.stream().allMatch(p -> p.age > 20));
        System.out.println(people.stream().noneMatch(p -> p.age > 40));

        // A comparator lambda in sorted(), then forEach.
        people.stream()
            .sorted((a, b) -> a.age - b.age)
            .forEach(p -> System.out.print(p.name + " "));
        System.out.println();                       // Alice Carol Bob

        // toSet gives a HashSet (JDK iteration order).
        List<Integer> nums = new ArrayList<>();
        nums.add(3); nums.add(1); nums.add(3); nums.add(2); nums.add(1);
        Set<Integer> uniq = nums.stream().collect(Collectors.toSet());
        System.out.println(uniq + " " + uniq.size());
    }
}
"#
);

differential_test!(
    diff_stream_joining_limit_skip,
    "DiffStreamJoin",
    r#"
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class DiffStreamJoin {
    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<>(Arrays.asList(3, 1, 3, 2, 1, 4));

        // distinct -> sorted -> map -> joining with prefix/suffix
        String joined = nums.stream()
            .distinct()
            .sorted()
            .map(n -> "" + n)
            .collect(Collectors.joining(", ", "[", "]"));
        System.out.println(joined);                 // [1, 2, 3, 4]

        // sorted -> skip -> limit
        List<Integer> window = nums.stream()
            .sorted()
            .skip(2)
            .limit(2)
            .collect(Collectors.toList());
        System.out.println(window);

        // plain joining
        System.out.println(nums.stream().distinct().sorted().map(n -> "" + n)
            .collect(Collectors.joining()));        // 1234
    }
}
"#
);

// ---------------------------------------------------------------------------
// java.util.Optional / OptionalInt / OptionalDouble — present-or-absent values
// from the stream terminals (findFirst / max / min / average).
// ---------------------------------------------------------------------------

// Optional.map(function) transforms a present value (its element erased, like a
// stream's map); orElseGet(supplier) computes a fallback only when absent.
differential_test!(
    diff_optional_map,
    "DiffOptionalMap",
    r#"
import java.util.Optional;

public class DiffOptionalMap {
    public static void main(String[] args) {
        Optional<String> a = Optional.of("hello");
        System.out.println(a.map(s -> s.length()).get());
        System.out.println(a.map(s -> s.toUpperCase()).get());
        System.out.println(a.map(s -> s + "!").orElse("none"));

        Optional<String> e = Optional.empty();
        System.out.println(e.map(s -> s.length()).isPresent());
        System.out.println(e.map(s -> s + "!").orElse("none"));

        // orElseGet: the value when present, the supplier's result when absent.
        System.out.println(a.orElseGet(() -> "fallback"));
        System.out.println(e.orElseGet(() -> "fallback"));
        Optional<Integer> n = Optional.empty();
        System.out.println(n.orElseGet(() -> 3 * 14));
        Optional<Integer> present = Optional.of(5);
        System.out.println(present.orElseGet(() -> 100));

        // A map that yields null becomes an empty Optional.
        System.out.println(a.map(s -> (String) null).isPresent());
    }
}
"#
);

// Optional.ifPresent(consumer) runs its lambda only when present; filter keeps
// a present value only if it matches (else empty). Both lambdas are typed by the
// Optional's element.
differential_test!(
    diff_optional_lambdas,
    "DiffOptionalLambda",
    r#"
import java.util.Optional;

public class DiffOptionalLambda {
    public static void main(String[] args) {
        Optional<String> a = Optional.of("hello");
        a.ifPresent(s -> System.out.println("len " + s.length()));
        Optional<String> b = Optional.empty();
        b.ifPresent(s -> System.out.println("never"));

        Optional<Integer> n = Optional.of(7);
        System.out.println(n.filter(x -> x > 5).isPresent());
        System.out.println(n.filter(x -> x > 10).isPresent());
        System.out.println(n.filter(x -> x > 5).get());
        System.out.println(b.filter(s -> s.length() > 0).isPresent());

        Optional<String> c = Optional.of("world");
        System.out.println(c.filter(s -> s.startsWith("w")).orElse("none"));
        System.out.println(c.filter(s -> s.startsWith("z")));
    }
}
"#
);

// orElse on a PRIMITIVE-element Optional: both arms must yield the unboxed
// element (present value and fallback alike), so `println(opt.orElse(-1))`
// dispatches `(I)V` and works whichever arm runs. The fallback used to cross
// boxed while the present value crossed unboxed, and the empty case died.
differential_test!(
    diff_optional_or_else_primitive,
    "DiffOptionalOrElse",
    r#"
import java.util.ArrayList;
import java.util.Optional;

public class DiffOptionalOrElse {
    public static void main(String[] args) {
        ArrayList<Integer> nums = new ArrayList<>();
        nums.add(5);
        nums.add(12);
        Optional<Integer> found = nums.stream().filter(n -> n > 10).findFirst();
        Optional<Integer> missing = nums.stream().filter(n -> n > 100).findFirst();
        System.out.println(found.orElse(-1));
        System.out.println(missing.orElse(-1));
        int got = missing.orElse(-1);
        System.out.println(got + 1);

        ArrayList<Double> ds = new ArrayList<>();
        ds.add(2.5);
        System.out.println(ds.stream().filter(x -> x > 3.0).findFirst().orElse(-1.5));

        // The erased Optional<Object> a map() produces takes a REFERENCE default.
        Optional<String> word = Optional.of("apple");
        Optional<String> none = Optional.empty();
        System.out.println(word.map(w -> w + "!").orElse("empty"));
        System.out.println(none.map(w -> w + "!").orElse("empty"));
    }
}
"#
);

// A CHAINED Optional receiver types its lambdas: `filter` keeps the element,
// `map` erases it to Object, and a stream's findFirst/max/min terminal
// carries the stream's element into the Optional it returns — so
// `list.stream().filter(p).findFirst().ifPresent(x -> ...)` compiles instead
// of only working when the Optional is first parked in a variable.
differential_test!(
    diff_optional_chained_receivers,
    "DiffOptionalChain",
    r#"
import java.util.ArrayList;
import java.util.Optional;

public class DiffOptionalChain {
    public static void main(String[] args) {
        Optional<String> word = Optional.of("apple");
        System.out.println(word.filter(w -> w.length() > 3).filter(w -> w.startsWith("a")).orElse("no"));
        System.out.println(word.filter(w -> w.length() > 3).filter(w -> w.startsWith("z")).orElse("no"));
        word.filter(w -> w.length() > 3).ifPresent(w -> System.out.println("hit " + w));

        ArrayList<Integer> nums = new ArrayList<>();
        nums.add(4);
        nums.add(11);
        nums.stream().filter(n -> n > 10).findFirst().ifPresent(n -> System.out.println("first " + (n + 1)));
        nums.stream().max((a, b) -> a - b).ifPresent(n -> System.out.println("max " + n));
        nums.stream().min((a, b) -> a - b).map(n -> n * 2).ifPresent(n -> System.out.println("min2 " + n));

        word.map(w -> w + "!").filter(o -> o.toString().length() > 5).ifPresent(o -> System.out.println("obj " + o));
    }
}
"#
);

// The Optional factories: of(x)/ofNullable(x) build a present Optional,
// empty() an absent one, so a method can construct and return an Optional
// rather than only receive one from a stream terminal.
differential_test!(
    diff_optional_factories,
    "DiffOptionalFactory",
    r#"
import java.util.Optional;

public class DiffOptionalFactory {
    static Optional<String> lookup(int key) {
        if (key == 1) return Optional.of("one");
        if (key == 2) return Optional.ofNullable("two");
        return Optional.empty();
    }

    public static void main(String[] args) {
        Optional<Integer> a = Optional.of(42);
        System.out.println(a.isPresent() + " " + a.get() + " " + a);   // true 42 Optional[42]

        Optional<String> e = Optional.empty();
        System.out.println(e.isPresent() + " " + e.isEmpty() + " " + e.orElse("x") + " " + e);

        Optional<Double> d = Optional.of(3.5);
        System.out.println(d.get() + " " + d);

        System.out.println(lookup(1).get());
        System.out.println(lookup(2).orElse("none"));
        System.out.println(lookup(9).isPresent() + " " + lookup(9).orElse("absent"));
    }
}
"#
);

