// ---------------------------------------------------------------------------
// Arrays.asList is a FIXED-SIZE, write-through view; Collections.nCopies is
// immutable
//
// caturra returned an independent mutable copy: `set` did not reach the array,
// `add` succeeded where a JDK throws, and nCopies allowed a `set`.
// ---------------------------------------------------------------------------

differential_test!(
    diff_arrays_aslist_is_a_view,
    "DiffAsList",
    r#"
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class DiffAsList {
    public static void main(String[] args) {
        String[] backing = { "a", "b", "c" };
        List<String> view = Arrays.asList(backing);

        // set() writes THROUGH to the array ...
        view.set(0, "Z");
        System.out.println(backing[0]);
        // ... and a change to the array shows in the list.
        backing[1] = "Y";
        System.out.println(view);

        // Length-changing operations throw; set() and sort() do not.
        try { view.add("d"); System.out.println("added"); }
        catch (UnsupportedOperationException e) { System.out.println("add UOE"); }
        try { view.remove(0); System.out.println("removed"); }
        catch (UnsupportedOperationException e) { System.out.println("remove UOE"); }
        Collections.sort(view);
        System.out.println(view + " " + Arrays.toString(backing));

        // The varargs form is a view too.
        List<String> varargs = Arrays.asList("p", "q");
        try { varargs.add("r"); }
        catch (UnsupportedOperationException e) { System.out.println("varargs UOE"); }
        varargs.set(1, "z");
        System.out.println(varargs);

        // The read API is unaffected.
        System.out.println(view.size() + " " + view.get(0) + " "
            + view.contains("Z") + " " + view.indexOf("Z"));

        // A copy through the constructor is independent and mutable.
        List<String> copy = new java.util.ArrayList<>(Arrays.asList("m", "n"));
        copy.add("o");
        System.out.println(copy);

        // Collections.nCopies is IMMUTABLE.
        List<String> repeated = Collections.nCopies(3, "x");
        System.out.println(repeated + " " + repeated.size() + " " + repeated.get(1));
        try { repeated.set(0, "y"); System.out.println("set ok"); }
        catch (UnsupportedOperationException e) { System.out.println("nCopies UOE"); }
    }
}
"#
);

// ---------------------------------------------------------------------------
// Formatter: flag/width validation and rendering corners
// ---------------------------------------------------------------------------

// Validation the JDK does BEFORE looking at the argument. caturra rendered
// these silently — the accepts-invalid direction. Each is caught by class name
// so the output is deterministic and the class is confirmed catchable.
differential_test!(
    diff_format_validation,
    "DiffFormatValidation",
    r#"
public class DiffFormatValidation {
    public static void main(String[] args) {
        try { String.format("%--5s", "a"); } catch (Exception e) { System.out.println(e.getClass().getSimpleName() + ": " + e.getMessage()); }
        try { String.format("%<s", "a"); } catch (Exception e) { System.out.println(e.getClass().getSimpleName() + ": " + e.getMessage()); }
        try { String.format("%-d", 1); } catch (Exception e) { System.out.println(e.getClass().getSimpleName()); }
        try { String.format("%0d", 1); } catch (Exception e) { System.out.println(e.getClass().getSimpleName()); }
        try { String.format("%5n"); } catch (Exception e) { System.out.println(e.getClass().getSimpleName()); }
        try { String.format("%.2%"); } catch (Exception e) { System.out.println(e.getClass().getSimpleName()); }
        try { String.format("%#g", 1.0); } catch (Exception e) { System.out.println(e.getClass().getSimpleName()); }
        // The forms that stay LEGAL, so the checks are not too broad.
        System.out.println(String.format("[%-5s]", "a"));
        System.out.println(String.format("[%05d]", 42));
        System.out.println(String.format("%s=%<S", "x"));
    }
}
"#
);

differential_test!(
    diff_format_rendering_corners,
    "DiffFormatRendering",
    r#"
public class DiffFormatRendering {
    public static void main(String[] args) {
        // The # radix prefix comes before the zero padding.
        System.out.println(String.format("%#010x", 255));
        System.out.println(String.format("%#08X", 255));
        System.out.println(String.format("%#o", 8));
        // The ( flag parenthesizes a negative infinity.
        System.out.println(String.format("%(f", Double.NEGATIVE_INFINITY));
        System.out.println(String.format("%(f", Double.POSITIVE_INFINITY));
        System.out.println(String.format("%(f", -2.5));
        // Precision truncates %b like %s.
        System.out.println(String.format("%.2b", true));
        System.out.println(String.format("%.1s", "hello"));
        // The # flag keeps a trailing decimal point at precision 0.
        System.out.println(String.format("%#.0f", 3.0));
        System.out.println(String.format("%.0f", 3.0));
        // %g of zero is fixed with precision-1 fraction digits.
        System.out.println(String.format("%.1g", 0.0));
        System.out.println(String.format("%.4g", 0.0));
        System.out.println(String.format("%g", 0.0));
        // %c widens a byte or short to a char.
        System.out.println(String.format("%c%c%c", (byte) 72, (short) 105, 33));
    }
}
"#
);

// ---------------------------------------------------------------------------
// Streams are LAZY: interleaved side effects and short-circuiting
//
// The model was eager — every intermediate op ran over the whole vector — so
// side effects were STAGED (all peeks, then all filters) and a short-circuit
// terminal still evaluated the whole upstream, which could throw for an element
// a JDK never touches. Now the terminal PULLS one element at a time.
// ---------------------------------------------------------------------------

differential_test!(
    diff_streams_are_lazy,
    "DiffLazyStreams",
    r#"
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class DiffLazyStreams {
    public static void main(String[] args) {
        List<String> words = new ArrayList<>(Arrays.asList("a", "bb", "ccc"));
        List<Integer> nums = new ArrayList<>(Arrays.asList(1, 2, 3, 4, 5));

        // One element travels the whole pipeline before the next starts.
        words.stream()
            .peek(s -> System.out.println("peek " + s))
            .filter(s -> { System.out.println("filt " + s); return s.length() > 1; })
            .forEach(s -> System.out.println("out " + s));
        System.out.println("--");

        // findFirst stops the source; the filter never runs on 4 or 5.
        System.out.println(nums.stream()
            .filter(x -> { System.out.println("f " + x); return x == 3; })
            .findFirst().get());
        System.out.println("--");

        // limit stops an upstream peek.
        System.out.println(nums.stream()
            .peek(x -> System.out.println("p " + x))
            .limit(2).collect(Collectors.toList()));
        System.out.println("--");

        // The over-eager crash: findFirst returns before the element that would
        // divide by zero.
        List<Integer> danger = new ArrayList<>(Arrays.asList(1, 2, 0, 4));
        System.out.println(danger.stream().filter(x -> 10 / x > 0).findFirst().get());
        System.out.println("--");

        // The match terminals short-circuit.
        System.out.println(nums.stream().anyMatch(x -> { System.out.println("any " + x); return x == 2; }));
        System.out.println(nums.stream().allMatch(x -> { System.out.println("all " + x); return x < 3; }));
        System.out.println(nums.stream().noneMatch(x -> { System.out.println("none " + x); return x == 2; }));
        System.out.println("--");

        // sorted is a BARRIER: every pre-peek fires, then post-peek in order.
        List<Integer> jumbled = new ArrayList<>(Arrays.asList(3, 1, 2));
        jumbled.stream()
            .peek(x -> System.out.println("pre " + x))
            .sorted()
            .peek(x -> System.out.println("post " + x))
            .forEach(x -> System.out.println("s " + x));
        System.out.println("--");

        // distinct interleaves; skip drops the leading elements.
        List<Integer> dups = new ArrayList<>(Arrays.asList(1, 1, 2, 1, 3));
        dups.stream().peek(x -> System.out.println("d " + x)).distinct().forEach(x -> System.out.println("u " + x));
        System.out.println(nums.stream().skip(3).collect(Collectors.toList()));
        System.out.println("--");

        // IntStream: findFirst (now present, OptionalInt), a mapper bounded by
        // limit, and sum/range.
        System.out.println(IntStream.range(1, 10).filter(x -> x % 3 == 0).findFirst().getAsInt());
        System.out.println(IntStream.range(1, 20).limit(3).mapToObj(x -> "n" + x).collect(Collectors.joining(",")));
        System.out.println(IntStream.range(1, 5).map(x -> x * x).sum());
    }
}
"#
);

// ---------------------------------------------------------------------------
// StringBuilder: behavior, dispatch, and JDK 11 messages
// ---------------------------------------------------------------------------

// Behaviour + constructor/dispatch features.
differential_test!(
    diff_string_builder_features,
    "DiffSbFeatures",
    r#"
public class DiffSbFeatures {
    public static void main(String[] args) {
        // new StringBuilder(otherBuilder) copies the contents (independent).
        StringBuilder src = new StringBuilder("dup");
        StringBuilder copy = new StringBuilder(src);
        copy.append("!");
        System.out.println(copy + " " + src);

        // %s of a StringBuilder, and a cast of null to StringBuilder.
        StringBuilder ab = new StringBuilder("ab");
        System.out.println(String.format("[%s]", ab));
        StringBuilder nul = (StringBuilder) null;
        System.out.println(nul);
        System.out.println("x" + ab);

        // equals is Object IDENTITY — the classic trap.
        StringBuilder one = new StringBuilder("z");
        StringBuilder two = new StringBuilder("z");
        System.out.println(one.equals(two));
        System.out.println(one.equals(one));

        // append(char[], offset, len).
        char[] cs = { 'p', 'q', 'r', 's' };
        System.out.println(new StringBuilder().append(cs, 1, 2));

        // A negative capacity throws.
        try { new StringBuilder(-1); System.out.println("no throw"); }
        catch (NegativeArraySizeException e) { System.out.println("NASE " + e.getMessage()); }
    }
}
"#
);

// Exception messages match JDK 11 (several caturra had were JDK 17 wording, or
// had an extra space, or the wrong word).
differential_test!(
    diff_string_builder_messages,
    "DiffSbMessages",
    r#"
public class DiffSbMessages {
    static void show(int which) {
        try {
            StringBuilder b = new StringBuilder("abc");
            switch (which) {
                case 0: b.charAt(3); break;
                case 1: b.setCharAt(3, 'z'); break;
                case 2: b.deleteCharAt(3); break;
                case 3: new StringBuilder("hello").insert(9, "Z"); break;
                case 4: new StringBuilder("abcdef").substring(2, 99); break;
                case 5: new StringBuilder("xyz").replace(9, 10, "q"); break;
                case 6: new StringBuilder("xyz").delete(9, 3); break;
                case 7: b.setLength(-1); break;
                case 8: b.appendCodePoint(-1); break;
                case 9: b.appendCodePoint(0x110000); break;
                case 10: "abcdef".substring(2, 99); break;
                default: break;
            }
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
    }
    public static void main(String[] args) {
        for (int i = 0; i <= 10; i++) {
            show(i);
        }
    }
}
"#
);

