// NOT ambiguous: one declaration reached along two diamond paths, a class's
// own declaration hiding what it inherits, and qualified access.
differential_test!(
    diff_interface_constant_unambiguous,
    "DiffConstOk",
    r#"
interface CA { int K = 1; }
interface CB extends CA { }
class Fine implements CA, CB {
    int get() { return K; }
}
interface CC { int K = 9; }
class Hides implements CA, CC {
    static final int K = 42;
    int get() { return K; }
}
public class DiffConstOk {
    public static void main(String[] a) {
        System.out.println(new Fine().get());
        System.out.println(new Hides().get());
        System.out.println(CA.K + " " + CC.K);
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-6 switch labels and scoping: constant-expression labels, constant
// variables, the single switch-block scope, and JLS §16.2.9 definite
// assignment across case groups.

// JLS §15.28/§15.29: arithmetic, shifts, string concatenation, and `final`
// constant variables are all legal case labels — caturra accepted only bare
// literals and static-final field names.
differential_test!(
    diff_switch_constant_labels,
    "DiffSwitchConstLabels",
    r#"
public class DiffSwitchConstLabels {
    public static void main(String[] a) {
        int x = 13;
        switch (x) {
            case 2 * 3 + 7: System.out.println("13"); break;
            case 1 << 4: System.out.println("16"); break;
            default: System.out.println("d");
        }
        switch ("hello") {
            case "he" + "llo": System.out.println("concat"); break;
            default: System.out.println("d");
        }
        final int K = 10;
        final String S = "go";
        switch (12) {
            case K + 2: System.out.println("K+2"); break;
            case K: System.out.println("K"); break;
            default: System.out.println("d");
        }
        switch ("go") {
            case S: System.out.println("S"); break;
            default: System.out.println("d");
        }
        char c = 'b';
        switch (c) {
            case 'a' + 1: System.out.println("b"); break;
            default: System.out.println("d");
        }
        switch (3) {
            case -1 >>> 30: System.out.println("ushr"); break;
            default: System.out.println("d");
        }
        // Shift folding feeds constant narrowing too; a LONG shift stays a
        // runtime computation (the folder never sees long literals).
        byte b = 1 << 3;
        final long L = 1L << 40;
        System.out.println(b + " " + L);
    }
}
"#
);

// The switch block is ONE scope (JLS §6.3): declare in one group, assign and
// use in a later one.
differential_test!(
    diff_switch_single_scope,
    "DiffSwitchScope",
    r#"
public class DiffSwitchScope {
    public static void main(String[] a) {
        int x = 2;
        switch (x) {
            case 1:
                int v;
                v = 1;
                System.out.println("one " + v);
                break;
            case 2:
                v = 20;
                System.out.println("two " + v);
                break;
        }
        // Fall-through: assigning in the fallen-into group before reading.
        switch (x) {
            case 2: int w = 10;
            case 3: w = 5; System.out.println(w); break;
        }
    }
}
"#
);

// A folded label colliding with a literal is a duplicate; a non-constant
// local is not a label; a redeclaration across groups is already-defined;
// reading a variable declared in an earlier group without assignment is a
// definite-assignment error (v IS in scope — the message used to claim it
// did not exist).
differential_wording!(
    reject_switch_duplicate_folded_label,
    "RejSwitchDupFold",
    r#"
public class RejSwitchDupFold {
    public static void main(String[] a) {
        switch (1) {
            case 13: System.out.println("a"); break;
            case 2 * 3 + 7: System.out.println("b"); break;
        }
    }
}
"#
);

differential_wording!(
    reject_switch_nonconstant_label,
    "RejSwitchNonConst",
    r#"
public class RejSwitchNonConst {
    public static void main(String[] a) {
        int k = 5;
        switch (k) {
            case k: System.out.println("k"); break;
        }
    }
}
"#
);

differential_reject!(
    reject_switch_redeclaration_across_groups,
    "RejSwitchRedecl",
    r"
public class RejSwitchRedecl {
    public static void main(String[] a) {
        switch (1) {
            case 1: int v = 1; break;
            case 2: int v = 2; break;
        }
    }
}
"
);

differential_wording!(
    reject_switch_cross_group_definite_assignment,
    "RejSwitchDA",
    r"
public class RejSwitchDA {
    public static void main(String[] a) {
        int x = 2;
        switch (x) {
            case 1: int v = 10;
            case 2: System.out.println(v);
        }
    }
}
"
);

// ---------------------------------------------------------------------------
// Round-6 StringBuilder subranges: the CharSequence/char[] sub-range
// overloads, the JDK's exact bounds exceptions, self-insert aliasing, and
// null casts to interface types.

// append(CharSequence,int,int), insert(int,CharSequence),
// insert(int,char[],int,int), insert(int,CharSequence,int,int) — including
// null (which reads as "null") and a plain String argument picking the
// CharSequence overload.
differential_test!(
    diff_stringbuilder_subrange_overloads,
    "DiffSbSubranges",
    r#"
public class DiffSbSubranges {
    public static void main(String[] a) {
        StringBuilder sb = new StringBuilder("x");
        sb.append((CharSequence) "abcd", 1, 3);
        System.out.println(sb);
        sb.append((CharSequence) null, 1, 3);
        System.out.println(sb);
        sb.append("abcd", 0, 2);
        System.out.println(sb);
        StringBuilder v = new StringBuilder("xy");
        v.insert(1, new char[] {'a', 'b', 'c', 'd'}, 1, 2);
        System.out.println(v);
        v.insert(0, (CharSequence) "hello", 1, 3);
        System.out.println(v);
        StringBuilder other = new StringBuilder("PQ");
        v.insert(1, other);
        System.out.println(v);
        v.append(other, 0, 1);
        System.out.println(v);
        System.out.println(new StringBuilder((CharSequence) "seed"));
    }
}
"#
);

// JDK 11's insert(int, CharSequence) copies in place AFTER shifting, so a
// self-insert reads the already-shifted chars; the Object overload snapshots
// via String.valueOf. Both directions pinned.
differential_test!(
    diff_stringbuilder_self_insert_aliasing,
    "DiffSbSelfInsert",
    r#"
public class DiffSbSelfInsert {
    public static void main(String[] a) {
        StringBuilder sb = new StringBuilder("ab");
        sb.append(sb);
        System.out.println(sb);
        sb.insert(1, sb);
        System.out.println(sb + "|" + sb.length());
        StringBuilder t = new StringBuilder("cd");
        t.insert(0, (Object) t);
        System.out.println(t);
        StringBuilder u = new StringBuilder("ef");
        u.append(u, 0, 2);
        System.out.println(u);
    }
}
"#
);

// The sub-range bounds failures: class AND message — checkRange's plain
// IndexOutOfBoundsException ("start S, end E, length L", unclamped, end
// computed with int addition) for append and the CharSequence insert, the
// String-flavored one for the char[] insert, and the destination-offset
// check firing first.
differential_test!(
    diff_stringbuilder_subrange_bounds,
    "DiffSbBounds",
    r#"
public class DiffSbBounds {
    static void show(Exception e) {
        System.out.println(e.getClass().getName() + " | " + e.getMessage());
    }
    public static void main(String[] a) {
        StringBuilder sb = new StringBuilder("hi");
        char[] arr = {'x', 'y'};
        try { sb.append(arr, 1, 2); } catch (Exception e) { show(e); }
        try { sb.append(arr, -1, 1); } catch (Exception e) { show(e); }
        try { sb.append(arr, 3, 0); } catch (Exception e) { show(e); }
        try { sb.append((CharSequence) "abcd", 1, 5); } catch (Exception e) { show(e); }
        try { sb.append((CharSequence) null, 1, 5); } catch (Exception e) { show(e); }
        try { sb.append((CharSequence) "abcd", 3, 1); } catch (Exception e) { show(e); }
        try { sb.insert(9, arr, 0, 1); } catch (Exception e) { show(e); }
        try { sb.insert(1, arr, -1, 1); } catch (Exception e) { show(e); }
        try { sb.insert(1, arr, 2, -1); } catch (Exception e) { show(e); }
        try { sb.insert(9, (CharSequence) "abcd", 0, 1); } catch (Exception e) { show(e); }
        try { sb.insert(1, (CharSequence) "abcd", 2, 9); } catch (Exception e) { show(e); }
        try { sb.insert(1, (CharSequence) "abcd", 3, 2); } catch (Exception e) { show(e); }
        try { sb.insert(-1, (CharSequence) "abcd"); } catch (Exception e) { show(e); }
        System.out.println(sb);
    }
}
"#
);

// JLS §5.5: null casts to ANY reference type — the overload-selection idiom
// — and an interface downcast still checks at runtime.
differential_test!(
    diff_null_cast_to_interface,
    "DiffNullCastIface",
    r#"
public class DiffNullCastIface {
    public static void main(String[] a) {
        CharSequence c = (CharSequence) null;
        System.out.println(c == null);
        Comparable<String> p = (Comparable<String>) null;
        System.out.println(p == null);
        Object o = "boxed";
        CharSequence down = (CharSequence) o;
        System.out.println(down.length() + " " + down.charAt(1));
        Object plain = new Object();
        try {
            CharSequence bad = (CharSequence) plain;
            System.out.println("no-throw " + bad);
        } catch (ClassCastException e) {
            System.out.println("CCE");
        }
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-6 exception traces: traces fill at CONSTRUCTION (so rethrow keeps
// the original frames), the Caused by:/Suppressed: blocks with "... N more"
// elision, printStackTrace(System.out), and getSuppressed() typing.

// A caught-and-rethrown exception keeps the frames captured when it was
// CONSTRUCTED; wrap-and-rethrow prints the full Caused by: chain with the
// JDK's common-frame elision; a VM-raised exception (division by zero)
// chains the same way.
differential_test!(
    diff_trace_rethrow_and_cause,
    "DiffTraceCause",
    r#"
public class DiffTraceCause {
    static void origin() { throw new IllegalStateException("kept"); }
    static void deep() {
        try {
            throw new IllegalStateException("inner");
        } catch (IllegalStateException e) {
            throw new RuntimeException("outer", e);
        }
    }
    static void mid() { deep(); }
    public static void main(String[] a) {
        try {
            try {
                origin();
            } catch (IllegalStateException e) {
                throw e;
            }
        } catch (IllegalStateException e) {
            e.printStackTrace(System.out);
        }
        try {
            mid();
        } catch (RuntimeException e) {
            e.printStackTrace(System.out);
        }
        try {
            int x = 1 / 0;
        } catch (ArithmeticException e) {
            new RuntimeException("wrap-vm", e).printStackTrace(System.out);
        }
        System.out.println("done");
    }
}
"#
);

// try-with-resources: the close() failure prints as a tab-indented
// Suppressed: block, with its own frames and elision.
differential_test!(
    diff_trace_suppressed_block,
    "DiffTraceSuppressed",
    r#"
class Res implements AutoCloseable {
    public void close() { throw new IllegalStateException("in close"); }
}
public class DiffTraceSuppressed {
    public static void main(String[] a) {
        try {
            try (Res r = new Res()) {
                throw new RuntimeException("in body");
            }
        } catch (RuntimeException e) {
            e.printStackTrace(System.out);
        }
        System.out.println("done");
    }
}
"#
);

// A user exception's trace names the `new` site (the constructor chain is
// hidden, as fillInStackTrace hides it), through a factory method.
differential_test!(
    diff_trace_user_exception,
    "DiffTraceUserEx",
    r#"
class TraceEx extends RuntimeException {
    TraceEx(String m) { super(m); }
}
public class DiffTraceUserEx {
    static TraceEx make() { return new TraceEx("custom"); }
    public static void main(String[] a) {
        make().printStackTrace(System.out);
        System.out.println("done");
    }
}
"#
);

// getSuppressed() is a Throwable[]: assignable, indexable, iterable, its
// elements answering getMessage()/getClass() without casts.
differential_test!(
    diff_get_suppressed_typed,
    "DiffSuppressedTyped",
    r#"
public class DiffSuppressedTyped {
    static class R implements AutoCloseable {
        String name;
        R(String n) { name = n; }
        public void close() { throw new IllegalStateException("close-" + name); }
    }
    public static void main(String[] a) {
        try {
            try (R r1 = new R("A"); R r2 = new R("B")) {
                throw new RuntimeException("body");
            }
        } catch (Exception e) {
            Throwable[] sup = e.getSuppressed();
            System.out.println(sup.length);
            for (Throwable t : sup) {
                System.out.println(t.getClass().getName() + ": " + t.getMessage());
            }
            System.out.println("first: " + sup[0].getMessage());
        }
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-6 inheritance tail: Object methods through interface-typed
// references (JLS §9.2), and super.m() to a hidden static (JLS §15.12).

// Every interface implicitly declares the public Object methods, so
// toString/equals/hashCode/getClass all resolve through an interface-typed
// reference — variable, parameter, or collection element.
differential_test!(
    diff_interface_object_methods,
    "DiffIfaceObjMethods",
    r#"
import java.util.ArrayList;
import java.util.List;
interface Tagged { String tag(); }
class Card implements Tagged {
    public String tag() { return "c"; }
    @Override public String toString() { return "Card!"; }
}
public class DiffIfaceObjMethods {
    static String describe(Tagged t) { return t.toString() + "/" + t.getClass().getSimpleName(); }
    public static void main(String[] args) {
        Tagged i = new Card();
        System.out.println(i.toString());
        System.out.println(i.equals(i) + " " + i.equals(new Card()));
        System.out.println(i.hashCode() == i.hashCode());
        System.out.println(i.getClass().getName());
        System.out.println(describe(i));
        List<Tagged> all = new ArrayList<>();
        all.add(i);
        for (Tagged t : all) {
            System.out.println(t.toString());
        }
    }
}
"#
);

// `super.m()` naming a HIDDEN static resolves statically to the
// superclass's method — including one the superclass itself inherited —
// while instance super calls beside it behave as ever.
differential_test!(
    diff_super_hidden_static,
    "DiffSuperStatic",
    r#"
class Grand { static String s() { return "grand"; } String v() { return "gv"; } }
class Parent extends Grand { }
class Child extends Parent {
    static String s() { return "child"; }
    String call() { return super.s() + "/" + super.v() + "/" + s(); }
}
public class DiffSuperStatic {
    public static void main(String[] args) {
        System.out.println(new Child().call());
    }
}
"#
);

// ...but `super.m()` to an ABSTRACT method stays an error on both engines.
differential_reject!(
    reject_super_abstract_method,
    "RejSuperAbstract",
    r#"
abstract class Abs { abstract String m(); }
class Impl extends Abs {
    String m() { return "b"; }
    String call() { return super.m(); }
}
public class RejSuperAbstract {
    public static void main(String[] args) {
        System.out.println(new Impl().call());
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-7 finally + static-init: a finally's own abrupt exit still runs the
// ENCLOSING finallys; the entry class initializes at startup; a failed
// <clinit> poisons the class; interfaces with defaults initialize with their
// implementor; an escaping <clinit> exception wraps in EIIE.

// JLS §14.20.2: when an inner finally's return/break discards a pending
// return, every enclosing finally (and try-with-resources close) still runs
// — and an outer finally's overriding return wins.
differential_test!(
    diff_finally_discards_pending_return,
    "DiffFinallyDiscard",
    r#"
class Res7 implements AutoCloseable {
    public void close() { System.out.println("close V"); }
}
public class DiffFinallyDiscard {
    static int v = 0;
    static int f1() {
        try {
            try { return 10; } finally { return 20; }
        } finally { System.out.println("outer finally"); }
    }
    static int f2() {
        try {
            try { return 10; } finally { return 20; }
        } finally { return 30; }
    }
    static int f3() {
        int i = 0;
        while (true) {
            try {
                try { return 1; } finally { System.out.println("inner fin"); break; }
            } finally { System.out.println("outer fin"); }
        }
        return 42;
    }
    static int f4() {
        try (Res7 r = new Res7()) {
            try { return 1; } finally { return 2; }
        }
    }
    static int f5() {
        try {
            try { throw new RuntimeException("x"); } finally { return 7; }
        } finally { System.out.println("outer5"); }
    }
    static int f6() {
        try { return v; } finally { v = 99; }
    }
    public static void main(String[] a) {
        System.out.println(f1());
        System.out.println(f2());
        System.out.println(f3());
        System.out.println(f4());
        System.out.println(f5());
        v = 41;
        System.out.println(f6() + " " + v);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 3; i++) {
            try {
                try {
                    if (i == 1) continue;
                    sb.append("b").append(i);
                } finally { sb.append("F").append(i); }
            } finally { sb.append("G").append(i); }
        }
        System.out.println(sb);
    }
}
"#
);

// JVMS §5.5: invoking main is an active use — the entry class's static
// initializers (superclass first) run before main's first statement.
differential_test!(
    diff_main_class_static_init,
    "DiffMainClinit",
    r#"
class SupInit { static { System.out.println("Sup static"); } }
public class DiffMainClinit extends SupInit {
    static { System.out.println("Main static"); }
    static int seeded = seed();
    static int seed() { System.out.println("field init"); return 7; }
    public static void main(String[] args) {
        System.out.println("main body " + seeded);
    }
}
"#
);

// JLS §12.4.2: after a <clinit> failure the class is erroneous — every later
// active use (field, static call, new) throws NoClassDefFoundError, and the
// constructor must NOT run. The failure itself surfaces as
// ExceptionInInitializerError.
differential_test!(
    diff_failed_init_poisons_class,
    "DiffInitPoison",
    r#"
class BadInit {
    static int x = boom();
    static int boom() { throw new RuntimeException("kaboom"); }
    static void go() { System.out.println("never"); }
    BadInit() { System.out.println("ctor ran"); }
}
public class DiffInitPoison {
    public static void main(String[] args) {
        try { int q = BadInit.x; } catch (Throwable t) { System.out.println("1: " + t.getClass().getName()); }
        try { int q = BadInit.x; } catch (Throwable t) { System.out.println("2: " + t.getClass().getName()); }
        try { BadInit.go(); } catch (Throwable t) { System.out.println("3: " + t.getClass().getName() + " | " + t.getMessage()); }
        try { new BadInit(); } catch (Throwable t) { System.out.println("4: " + t.getClass().getName()); }
        System.out.println("end");
    }
}
"#
);

// JVMS §5.5: initializing a class initializes its superinterfaces that
// declare DEFAULT methods (before the class); an interface without defaults
// waits for a direct use of its non-constant field.
differential_test!(
    diff_interface_default_init_order,
    "DiffIfaceInitOrder",
    r#"
interface WithDefault { int K = DiffIfaceInitOrder.mark("DI"); default void d() {} }
interface NoDefault { int K2 = DiffIfaceInitOrder.mark("Plain"); }
class SupI implements NoDefault { static { System.out.println("Sup"); } }
class ImplI extends SupI implements WithDefault { static { System.out.println("Impl"); } }
public class DiffIfaceInitOrder {
    static int mark(String s) { System.out.println(s + " init"); return 1; }
    public static void main(String[] a) {
        System.out.println("start");
        new ImplI();
        System.out.println("mid");
        System.out.println(WithDefault.K + " " + NoDefault.K2);
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-7 arrays: runtime store checks (JLS §10.5), arraycopy's JVM checks
// and messages, and the array-aware corners of Class.

// Array covariance is checked AT THE STORE: an element that does not fit the
// array's runtime component type throws ArrayStoreException naming the
// offending value's class — including array-typed rows of a 2-D array, and a
// Number[] whose closed wrapper hierarchy caturra can decide.
differential_test!(
    diff_array_store_checks,
    "DiffArrayStore",
    r#"
public class DiffArrayStore {
    static void show(String tag, Throwable e) {
        System.out.println(tag + ": " + e.getClass().getName() + " | " + e.getMessage());
    }
    public static void main(String[] a) {
        Object[] o1 = new String[2];
        try { o1[0] = Integer.valueOf(1); } catch (Throwable e) { show("str", e); }
        o1[1] = "fits";
        System.out.println(o1[1]);
        Object[] o2 = new Number[2];
        try { o2[0] = "s"; } catch (Throwable e) { show("num", e); }
        o2[1] = Integer.valueOf(4);
        System.out.println(o2[1]);
        Object[] rows = new String[1][1];
        try { rows[0] = new Integer[] {5}; } catch (Throwable e) { show("row", e); }
        rows[0] = new String[] {"row"};
        System.out.println(((String[]) rows[0])[0]);
        // An Object[] takes anything, including a primitive array.
        Object[] any = new Object[2];
        any[0] = new int[] {1};
        any[1] = "any";
        System.out.println(((int[]) any[0])[0] + " " + any[1]);
    }
}
"#
);

// System.arraycopy's own checks, in the JVM's order and wording: type
// mismatch first, then source index, destination index, negative length, and
// the two last-index checks — with "object array" naming every reference
// array, as the JVM does.
differential_test!(
    diff_arraycopy_checks_and_messages,
    "DiffArrayCopyChecks",
    r#"
import java.util.Arrays;
public class DiffArrayCopyChecks {
    static void show(String tag, Throwable e) {
        System.out.println(tag + ": " + e.getClass().getName() + " | " + e.getMessage());
    }
    public static void main(String[] a) {
        int[] si = {1, 2, 3};
        int[] di = new int[3];
        String[] ss = {"a", "b", "c"};
        String[] ds = new String[3];
        double[] sd = new double[3];
        try { System.arraycopy(si, -1, di, 0, 2); } catch (Throwable e) { show("A", e); }
        try { System.arraycopy(si, 0, di, 0, -1); } catch (Throwable e) { show("B", e); }
        try { System.arraycopy(si, 2, di, 0, 2); } catch (Throwable e) { show("C", e); }
        try { System.arraycopy(si, 0, di, 2, 2); } catch (Throwable e) { show("D", e); }
        try { System.arraycopy(si, 0, di, -1, 1); } catch (Throwable e) { show("E", e); }
        try { System.arraycopy(ss, 2, ds, 0, 2); } catch (Throwable e) { show("F", e); }
        try { System.arraycopy(sd, 2, new double[3], 0, 2); } catch (Throwable e) { show("G", e); }
        try { System.arraycopy(si, 0, sd, 0, 1); } catch (Throwable e) { show("H", e); }
        try { System.arraycopy(si, 0, ds, 0, 1); } catch (Throwable e) { show("I", e); }
        try { System.arraycopy(si, -1, di, 0, -1); } catch (Throwable e) { show("J", e); }
        try { System.arraycopy(si, 0, di, -1, -1); } catch (Throwable e) { show("K", e); }
        // A reference copy whose elements do not all fit copies the prefix
        // that does, then throws — a partially written destination.
        Object[] mixed = {"a", "b", Integer.valueOf(3), "d"};
        String[] dst = new String[4];
        dst[3] = "keep";
        try { System.arraycopy(mixed, 0, dst, 0, 4); } catch (Throwable e) { show("M", e); }
        System.out.println(Arrays.toString(dst));
        // Legal copies, including self-overlap in both directions.
        int[] ov = {1, 2, 3, 4, 5};
        System.arraycopy(ov, 0, ov, 1, 3);
        System.out.println(Arrays.toString(ov));
        String[] sov = {"a", "b", "c"};
        System.arraycopy(sov, 0, sov, 1, 2);
        System.out.println(Arrays.toString(sov));
        Object[] widened = new Object[2];
        System.arraycopy(ss, 0, widened, 0, 2);
        System.out.println(Arrays.toString(widened));
    }
}
"#
);

// Class knows about arrays: isArray, getComponentType (null for a
// non-array), the descriptor binary name, and a simple name that spells the
// component plus []. Class.toString is "class <binary name>" — "interface"
// for an interface, bare for a primitive.
differential_test!(
    diff_class_array_reflection,
    "DiffClassArray",
    r#"
interface Marker { }
class Holder implements Marker { }
public class DiffClassArray {
    public static void main(String[] a) {
        System.out.println(new int[0].getClass().isArray() + " " + String.class.isArray());
        System.out.println(new int[0].getClass().getComponentType() + " | " + String.class.getComponentType());
        System.out.println(new String[0][0].getClass().getComponentType().getName());
        System.out.println(new int[0].getClass().getName() + " " + new int[0].getClass().getSimpleName());
        System.out.println(new String[0].getClass().getName() + " " + new String[0].getClass().getSimpleName());
        System.out.println(new int[0][0].getClass().getName() + " " + new int[0][0].getClass().getSimpleName());
        System.out.println(new Number[0].getClass().getName() + " " + new Number[0].getClass().getSimpleName());
        System.out.println(String.class + " | " + Holder.class + " | " + Marker.class);
        System.out.println(new int[0].getClass() + " | " + new String[0].getClass());
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-7 float/double: the wrappers' TOTAL order (NaN greatest, -0.0 < 0.0)
// in every sorted structure, Java's parse grammar for the word forms, and the
// floating-literal shapes the lexer did not know.

// Double/Float impose a total order (JLS §4.2.3): NaN is greater than
// everything and equal to itself, -0.0 is strictly less than 0.0. Comparing
// primitively made every NaN comparison "equal", which swallowed a TreeSet,
// hid NaN from Collections.max, and mis-ordered a PriorityQueue.
differential_test!(
    diff_double_total_order,
    "DiffDoubleOrder",
    r#"
import java.util.*;
public class DiffDoubleOrder {
    public static void main(String[] args) {
        TreeSet<Double> ts = new TreeSet<>();
        ts.add(1.0); ts.add(Double.NaN); ts.add(-0.0); ts.add(0.0);
        System.out.println(ts + " " + ts.size() + " " + ts.contains(Double.NaN));
        System.out.println(ts.first() + " " + ts.last() + " " + ts.higher(0.0));
        TreeMap<Double, String> tm = new TreeMap<>();
        tm.put(Double.NaN, "nan"); tm.put(0.0, "pos"); tm.put(-0.0, "neg"); tm.put(1.0, "one");
        System.out.println(tm + " " + tm.get(Double.NaN));
        System.out.println(tm.firstKey() + " " + tm.lastKey());
        System.out.println(Collections.max(Arrays.asList(3.0, Double.NaN, 1.0)));
        System.out.println(Collections.min(Arrays.asList(Double.NaN, 1.0, 5.0)));
        System.out.println(Collections.min(Arrays.asList(0.0, -0.0)) + " "
            + Collections.max(Arrays.asList(-0.0, 0.0)));
        PriorityQueue<Double> pq = new PriorityQueue<>();
        pq.add(3.0); pq.add(Double.NaN); pq.add(1.0); pq.add(-0.0); pq.add(0.0);
        StringBuilder sb = new StringBuilder();
        while (!pq.isEmpty()) sb.append(pq.poll()).append(" ");
        System.out.println(sb.toString().trim());
        List<Double> list = new ArrayList<>(Arrays.asList(3.0, Double.NaN, 1.0, -0.0, 0.0));
        Collections.sort(list);
        System.out.println(list);
        list.sort(Comparator.reverseOrder());
        System.out.println(list);
        List<Float> floats = new ArrayList<>(Arrays.asList(2.0f, Float.NaN, -0.0f, 0.0f));
        Collections.sort(floats);
        System.out.println(floats + " " + Collections.max(floats));
        // The identity relations these orders rest on, unchanged.
        System.out.println(Double.compare(Double.NaN, 1.0) + " " + Double.compare(-0.0, 0.0));
        System.out.println(Double.valueOf(Double.NaN).equals(Double.NaN) + " "
            + Double.valueOf(0.0).equals(-0.0) + " " + (Double.NaN == Double.NaN));
        Set<Double> hs = new HashSet<>(Arrays.asList(Double.NaN, Double.NaN, 0.0, -0.0));
        System.out.println(hs.size() + " " + hs.contains(Double.NaN));
        // Integers and Strings are untouched by the change.
        System.out.println(Collections.max(Arrays.asList(3, 1, 2)) + " "
            + Collections.max(Arrays.asList("b", "a", "c")));
    }
}
"#
);

// Java's parse grammar admits exactly `NaN` and `Infinity` as word forms,
// with an optional sign and no type suffix — not Rust's `inf`/`nan`.
differential_test!(
    diff_parse_double_grammar,
    "DiffParseDouble",
    r#"
public class DiffParseDouble {
    static void d(String s) {
        try { System.out.println("[" + s + "] -> " + Double.parseDouble(s)); }
        catch (Throwable e) {
            System.out.println("[" + s + "] -> " + e.getClass().getSimpleName() + ": " + e.getMessage());
        }
    }
    static void f(String s) {
        try { System.out.println("f[" + s + "] -> " + Float.parseFloat(s)); }
        catch (Throwable e) {
            System.out.println("f[" + s + "] -> " + e.getClass().getSimpleName() + ": " + e.getMessage());
        }
    }
    public static void main(String[] args) {
        String[] cases = {"NaN", "nan", "-NaN", "+NaN", "NaNd", "Infinity", "infinity", "INFINITY",
            "-Infinity", "+Infinity", "Infinityf", "inf", "-inf", "1.5", "1.5f", "1.5D", " 2.5 ",
            "1.", "+.5", "0x1.8p1", "1e400", "-1e400", "1e-400", "", "x", ".", "1e", "1.0e5f"};
        for (String s : cases) d(s);
        f("NaN"); f("nan"); f("Infinity"); f("inf"); f("1e40"); f("3.4e39");
    }
}
"#
);

// The floating-literal shapes JLS §3.10.2 allows: an optional fraction after
// the dot, hexadecimal literals with a mandatory binary exponent, and the
// range rules (too large when it rounds to infinity, too small when a
// NONZERO significand rounds to zero — `0e-400` is fine).
differential_test!(
    diff_float_literal_shapes,
    "DiffFloatLiterals",
    r#"
public class DiffFloatLiterals {
    public static void main(String[] args) {
        System.out.println(5. + " " + 5.d + " " + 2.f + " " + 5.e2 + " " + 5.e-2);
        System.out.println(0x1.fp3 + " " + 0x1p3 + " " + 0x1.8p1f + " " + 0x0.0p0 + " " + 0x1.8P1);
        System.out.println(1e-323 + " " + 0e-400 + " " + 0.0e999);
        System.out.println(1e-45f + " " + 3.4e38f + " " + 1.7976931348623157e308);
        // The integer literal forms beside them are unchanged.
        System.out.println(0xFF + " " + 0xFFL + " " + 0b1010 + " " + 0777 + " " + 1_000.5);
    }
}
"#
);

