// ---------------------------------------------------------------------------
// The String tail (audit round 8): identity, surrogates, and the API corners.
// ---------------------------------------------------------------------------

// The JDK returns THIS string when a range covers all of it, and `repeat(0)`
// answers the `""` literal — so each identity holds rather than allocating a
// copy. And a `char[]` round-trip must keep SURROGATE PAIRS: rendering unit by
// unit through a code point turned every non-BMP character into two U+FFFDs,
// and `indexOf(0xD83D)` (a real code unit of the string) answered -1.
differential_test!(
    diff_string_identity_and_surrogates,
    "DiffStringTail",
    r#"
public class DiffStringTail {
    public static void main(String[] args) {
        String s = "abcdef";
        System.out.println((s.substring(0) == s) + " " + (s.substring(0, s.length()) == s)
            + " " + (s.subSequence(0, s.length()) == s));
        System.out.println(("ab".repeat(1) == "ab") + " " + ("ab".repeat(0) == ""));
        System.out.println(s.substring(2) + " " + s.substring(1, 3) + " " + "ab".repeat(3));

        String emoji = "" + (char) 0xD83D + (char) 0xDE00 + "x";
        System.out.println(emoji.indexOf(0xD83D) + " " + emoji.lastIndexOf(0xDE00)
            + " " + emoji.indexOf('x'));
        String pair = "" + (char) 0xD83D + (char) 0xDE00;
        String back = String.valueOf(pair.toCharArray());
        System.out.println(back.codePointAt(0) + " " + pair.equals(back));
        char[] none = null;
        try { String.valueOf(none); } catch (NullPointerException e) { System.out.println("NPE"); }
    }
}
"#
);

// The API corners: `regionMatches` in both forms, `contentEquals` over the
// JDK's real `CharSequence` parameter (so a `CharSequence` variable, a
// `StringBuilder` and `null` all fit), `CASE_INSENSITIVE_ORDER`, the
// `subSequence` result's inherited `Object` methods, `join` over any
// `Iterable` and with a `StringBuilder` delimiter, and the bare
// NullPointerExceptions its null checks really throw.
differential_test!(
    diff_string_api_corners,
    "DiffStringCorners",
    r#"
import java.util.*;

public class DiffStringCorners {
    public static void main(String[] args) {
        String s = "Hello World";
        System.out.println(s.regionMatches(6, "World", 0, 5));
        System.out.println(s.regionMatches(true, 6, "WORLD", 0, 5));
        System.out.println(s.regionMatches(6, "WORLD", 0, 5));
        System.out.println(s.regionMatches(-1, "World", 0, 5) + " " + s.regionMatches(6, "World", 0, 99));

        CharSequence cs = "hey";
        System.out.println("hey".contentEquals(cs));
        System.out.println("hey".contentEquals(new StringBuilder("hey")));
        try { "x".contentEquals(null); } catch (NullPointerException e) { System.out.println("NPE"); }

        String[] names = {"Banana", "apple", "Cherry"};
        Arrays.sort(names, String.CASE_INSENSITIVE_ORDER);
        System.out.println(Arrays.toString(names));
        System.out.println(String.CASE_INSENSITIVE_ORDER.compare("apple", "Banana"));

        CharSequence sub = "abcdef".subSequence(1, 4);
        System.out.println(sub.equals("bcd") + " " + sub.hashCode());

        Set<String> set = new TreeSet<>(Arrays.asList("b", "a"));
        System.out.println(String.join("-", set));
        System.out.println(String.join(new StringBuilder("-"), "a", "b"));
        try { String.join(null, "a", "b"); } catch (NullPointerException e) {
            System.out.println("join " + e.getMessage());
        }
        System.out.println("ss".compareToIgnoreCase("SS") + " " + "ß".compareToIgnoreCase("SS"));
    }
}
"#
);

// ---------------------------------------------------------------------------
// The regex engine (audit round 8): what a pattern means, and where it errors.
// ---------------------------------------------------------------------------

// What a pattern MEANS: a quantifier after `\Q…\E` binds only the last quoted
// character, a `&&` intersection binds tighter than the class's negation, `$`
// does not fire between a final CR and LF, `[a-[b]]` is a union (not a range),
// a backreference to a group that does not exist simply never matches, and an
// ordinary alternation over a thousand characters must not exhaust the
// backtracking budget and report "no match".
differential_test!(
    diff_regex_semantics,
    "DiffRegexSemantics",
    r#"
import java.util.Arrays;

public class DiffRegexSemantics {
    public static void main(String[] args) {
        System.out.println("abb".matches("\\Qab\\E+") + " " + "abab".matches("\\Qab\\E+"));
        System.out.println("b".matches("[^a-c&&[^b]]") + " " + "a".matches("[^ab&&b-d]"));
        System.out.println("b".matches("[a-c&&[^b]]") + " " + "a".matches("[a-c&&[ab]]"));

        String out = "a\r\n".replaceAll("$", "X");
        System.out.println(out.length() + " " + out.replace("\r", "<CR>").replace("\n", "<LF>"));

        System.out.println("a".matches("[a-[b]]") + " " + "b".matches("[a-[b]]"));
        System.out.println("A".matches("\\1") + " " + "A".matches("(a)\\2"));

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 1000; i++) { sb.append('a'); }
        sb.append('c');
        System.out.println(sb.toString().replaceAll("a*b|c", "X").endsWith("X"));

        System.out.println(Arrays.toString("one\ntwo\r\nthree".split("\\R")));
        System.out.println("A".matches("\\x{41}") + " " + "é".matches("\\x{e9}"));
    }
}
"#
);

// Where a pattern ERRORS, and with which index: the JDK reports the cursor its
// parse stopped at, not where the construct began. Plus the replacement-string
// checks — a lone trailing backslash and a bare trailing `$` each have their
// own IllegalArgumentException.
differential_test!(
    diff_regex_errors,
    "DiffRegexErrors",
    r#"
public class DiffRegexErrors {
    static void pattern(String p) {
        try { "x".matches(p); System.out.println("ok"); }
        catch (RuntimeException e) { System.out.println(e.getMessage().split("\n")[0]); }
    }
    static void replace(String r) {
        try { System.out.println("abc".replaceAll("b", r)); }
        catch (RuntimeException e) { System.out.println(e.getMessage()); }
    }
    public static void main(String[] args) {
        pattern("a{2,1}");
        pattern("\\q");
        pattern("a)");
        pattern("(ab");
        pattern("a{x");
        pattern("[a-&&b]");
        replace("x\\");
        replace("x$");
        replace("x$1");
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-9 cluster: try-with-resources (JLS §14.20.3).
// ---------------------------------------------------------------------------

// A resource is closed EXACTLY ONCE, whether the body completes normally or
// abruptly. It used to close twice on the abrupt path, because the finally copy
// that `return`/`break`/`continue` inlines sat inside the protected range of the
// very try it was leaving — so when `close()` threw, the handler ran the close
// again and self-suppressed the second failure into the first.
differential_test!(
    diff_twr_close_once_on_abrupt_exit,
    "DiffTwrOnce",
    r#"
public class DiffTwrOnce {
    static class R implements AutoCloseable {
        String n;
        int calls = 0;
        R(String n) { this.n = n; }
        public void close() {
            calls++;
            System.out.println("close " + n + " #" + calls);
            throw new IllegalStateException("c-" + n);
        }
    }
    static R shared = new R("s");
    static void byReturn() {
        try (R a = shared) {
            return;
        } catch (IllegalStateException e) {
            System.out.println("caught " + e.getMessage() + " sup=" + e.getSuppressed().length);
        }
    }
    static void byBreakAndContinue() {
        for (int i = 0; i < 2; i++) {
            try (R a = new R("L" + i)) {
                if (i == 0) continue;
                break;
            } catch (IllegalStateException e) {
                System.out.println("loop " + e.getMessage() + " sup=" + e.getSuppressed().length);
            }
        }
    }
    static void several() {
        try (R a = new R("a"); R b = new R("b"); R c = new R("c")) {
            return;
        } catch (IllegalStateException e) {
            System.out.print("several " + e.getMessage());
            for (Throwable s : e.getSuppressed()) System.out.print(" sup " + s.getMessage());
            System.out.println();
        }
    }
    public static void main(String[] args) {
        byReturn();
        System.out.println("total " + shared.calls);
        byBreakAndContinue();
        several();
    }
}
"#
);

// The same range split, without any resource: an exception thrown by a finally
// copy inlined at a `return` must surface OUTSIDE its own try (so that try's
// finally does not re-run) but still INSIDE the enclosing one, whose catch and
// finally are exactly where Java delivers it.
differential_test!(
    diff_finally_copy_is_not_self_caught,
    "DiffFinallyCopy",
    r#"
public class DiffFinallyCopy {
    static String nested() {
        try {
            try {
                return "body";
            } finally { System.out.println("F2"); throw new IllegalStateException("from-F2"); }
        } catch (IllegalStateException e) {
            System.out.println("outer catch " + e.getMessage());
            return "caught";
        } finally { System.out.println("F1"); }
    }
    static String outerThrows() {
        try {
            try { return "b"; } finally { System.out.println("g-F2"); }
        } finally { System.out.println("g-F1"); throw new IllegalStateException("from-F1"); }
    }
    public static void main(String[] args) {
        System.out.println(nested());
        try { System.out.println(outerThrows()); }
        catch (IllegalStateException e) { System.out.println("main caught " + e.getMessage()); }
    }
}
"#
);

// One try-with-resources inside another's BODY. The synthetic locals live in the
// enclosing method's scope, so a per-statement counter was not enough to keep
// them apart and the program was refused outright.
differential_test!(
    diff_twr_nested_in_body,
    "DiffTwrNested",
    r#"
public class DiffTwrNested {
    static class R implements AutoCloseable {
        String n;
        R(String n) { this.n = n; }
        public void close() { System.out.println("close " + n); }
    }
    public static void main(String[] args) {
        try (R a = new R("out")) {
            try (R b = new R("in")) {
                System.out.println("nested body");
            }
            for (int i = 0; i < 2; i++) {
                try (R c = new R("loop" + i)) { System.out.println("loop body " + i); }
            }
        }
        try (R d = new R("after")) { System.out.println("after body"); }
        System.out.println("done");
    }
}
"#
);

// A FIELD ACCESS is a resource too (Java 9). The expression is read once, where
// the resource specification names it.
differential_test!(
    diff_twr_field_resource,
    "DiffTwrField",
    r#"
public class DiffTwrField {
    static class R implements AutoCloseable {
        String n;
        R(String n) { this.n = n; }
        public void close() { System.out.println("close " + n); }
    }
    final R inst = new R("inst");
    static final R stat = new R("stat");
    void instanceForm() {
        try (this.inst) { System.out.println("body1"); }
    }
    public static void main(String[] args) {
        DiffTwrField t = new DiffTwrField();
        try (t.inst) { System.out.println("body2"); }
        t.instanceForm();
        try (DiffTwrField.stat) { System.out.println("body3"); }
        System.out.println("done");
    }
}
"#
);

// An exception cannot suppress itself: the JDK refuses rather than building a
// cycle. A resource whose close() rethrows the body's own exception hits this.
differential_test!(
    diff_self_suppression_refused,
    "DiffSelfSuppress",
    r#"
public class DiffSelfSuppress {
    static RuntimeException shared = new RuntimeException("shared");
    static class R implements AutoCloseable {
        public void close() { throw shared; }
    }
    public static void main(String[] args) {
        try (R a = new R()) {
            throw shared;
        } catch (Throwable e) {
            System.out.println("caught " + e.getClass().getName() + ": " + e.getMessage());
            System.out.println("sup=" + e.getSuppressed().length);
        }
        RuntimeException e = new RuntimeException("x");
        try { e.addSuppressed(e); }
        catch (IllegalArgumentException x) { System.out.println("IAE " + x.getMessage()); }
        try { e.addSuppressed(null); }
        catch (NullPointerException x) { System.out.println("NPE " + x.getMessage()); }
        System.out.println("sup=" + e.getSuppressed().length);
    }
}
"#
);

// `AutoCloseable` is a functional interface, `Closeable` is a real java.io type
// that IS-A `AutoCloseable`, and a class may inherit `close()` as a DEFAULT from
// an interface rather than declaring it.
differential_test!(
    diff_closeable_shapes,
    "DiffCloseable",
    r#"
import java.io.Closeable;
import java.io.IOException;
public class DiffCloseable {
    interface Closeable2 extends AutoCloseable {
        default void close() { System.out.println("default close"); }
    }
    static class UsesDefault implements Closeable2 { }
    static class Io implements Closeable {
        public void close() throws IOException { System.out.println("io close"); }
    }
    public static void main(String[] args) throws Exception {
        try (AutoCloseable a = () -> System.out.println("lambda close")) {
            System.out.println("body");
        }
        try (UsesDefault u = new UsesDefault()) { System.out.println("default body"); }
        try (Closeable c = new Io()) { System.out.println("io body"); }
        new UsesDefault().close();
        System.out.println("done");
    }
}
"#
);

// javac: a resource must BE an AutoCloseable. Merely having a close() method is
// not enough, and accepting one ran a program a real JDK will not compile.
differential_reject!(
    reject_resource_not_autocloseable,
    "RejectResource",
    r#"
public class RejectResource {
    static class NotCloseable {
        public void close() { System.out.println("close"); }
    }
    public static void main(String[] args) {
        try (NotCloseable n = new NotCloseable()) {
            System.out.println("body");
        }
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-9 cluster: custom Iterable / Iterator (JLS §14.14.2).
// ---------------------------------------------------------------------------

// A program's own data structure in a for-each. `implements Iterable<T>` used to
// be refused outright ("cannot find symbol: class Iterable"), as did
// `implements Iterator<T>` — so the whole idiom was unavailable. The loop is the
// JLS translation: `iterator()`, then `hasNext`/`next`.
differential_test!(
    diff_custom_iterable,
    "DiffIterable",
    r#"
import java.util.*;
public class DiffIterable {
    static class Bag implements Iterable<String> {
        private List<String> items = new ArrayList<>();
        void add(String s) { items.add(s); }
        public Iterator<String> iterator() { return items.iterator(); }
    }
    static class Countdown implements Iterable<Integer> {
        int from;
        Countdown(int from) { this.from = from; }
        public Iterator<Integer> iterator() {
            return new Iterator<Integer>() {
                int n = from;
                public boolean hasNext() { return n > 0; }
                public Integer next() { return n--; }
            };
        }
    }
    static class Two implements Iterator<String> {
        int k = 0;
        public boolean hasNext() { return k < 2; }
        public String next() { return "m" + (k++); }
    }
    static <T> int count(Iterable<T> it) { int c = 0; for (T x : it) c++; return c; }
    public static void main(String[] args) {
        Bag b = new Bag();
        b.add("x"); b.add("y");
        for (String s : b) System.out.println("bag " + s);
        for (Object o : b) System.out.println("obj " + o);
        for (int n : new Countdown(3)) { if (n == 2) continue; System.out.println("n=" + n); }
        outer:
        for (String s : b) for (int n : new Countdown(2)) {
            System.out.println(s + n);
            if (n == 1) break outer;
        }
        System.out.println("count " + count(b) + " " + count(new Countdown(4)));
        Iterator<String> it = b.iterator();
        it.next(); it.remove();
        System.out.println("after remove " + count(b));
        Two u = new Two();
        while (u.hasNext()) System.out.println(u.next());
        Iterator<String> v = new Two();
        while (v.hasNext()) System.out.println(v.next());
        System.out.println(b instanceof Iterable);
    }
}
"#
);

// A cursor is an object: it assigns to `Object`, casts back down, answers
// `instanceof`, and has the `Object` methods. Each of these was refused or wrong
// — `getClass()` on any iterator claimed `java.lang.Object`, and the JDK's real
// iterator class names are observable.
differential_test!(
    diff_iterator_is_an_object,
    "DiffCursorObject",
    r#"
import java.util.*;
public class DiffCursorObject {
    static void show(String tag, Object o) { System.out.println(tag + " = " + o.getClass().getName()); }
    public static void main(String[] args) {
        List<String> al = new ArrayList<>(Arrays.asList("a", "b"));
        Iterator<String> i = al.iterator();
        Object o = i;
        System.out.println(o == i);
        System.out.println(((Iterator<String>) o).next());
        System.out.println(i instanceof Iterator);
        System.out.println(al instanceof Iterable);
        System.out.println(o instanceof Iterable);
        System.out.println(i.equals(i));
        System.out.println(i.equals(al.iterator()));
        System.out.println(i.toString().startsWith("java.util.ArrayList$Itr@"));
        show("ArrayList.iterator", al.iterator());
        show("ArrayList.listIterator", al.listIterator());
        show("Arrays.asList.iterator", Arrays.asList("x").iterator());
        show("Arrays.asList.listIterator", Arrays.asList("x").listIterator());
        Map<String, Integer> hm = new HashMap<>();
        hm.put("k", 1);
        show("HashMap.keySet", hm.keySet().iterator());
        show("HashMap.values", hm.values().iterator());
        show("HashMap.entrySet", hm.entrySet().iterator());
        show("HashSet", new HashSet<>(Arrays.asList("x")).iterator());
        TreeMap<String, Integer> tm = new TreeMap<>();
        tm.put("k", 1);
        show("TreeMap.keySet", tm.keySet().iterator());
        show("TreeMap.values", tm.values().iterator());
        show("TreeMap.entrySet", tm.entrySet().iterator());
        show("TreeSet", new TreeSet<>(Arrays.asList("x")).iterator());
        show("LinkedList", new LinkedList<>(Arrays.asList("x")).iterator());
        show("ArrayDeque", new ArrayDeque<>(Arrays.asList("x")).iterator());
        show("Stack", new Stack<String>().iterator());
    }
}
"#
);

// A method call on a DIAMOND copy constructor, in an argument position. The
// diamond's type was only known while emitting, so `type_of` answered `Null`,
// the call on it typed as `Error`, and the ENCLOSING call silently failed to
// resolve — compiling to its own argument and no call at all. Nothing was
// reported; the statement just did not run.
differential_test!(
    diff_diamond_copy_receiver_in_argument,
    "DiffDiamondArg",
    r#"
import java.util.*;
public class DiffDiamondArg {
    static void q(String tag, int n) { System.out.println("q " + tag + " " + n); }
    static void r(String tag, Object o) { System.out.println("r " + tag + " " + o); }
    public static void main(String[] args) {
        List<String> src = Arrays.asList("x", "y");
        q("list", new ArrayList<>(src).size());
        q("set", new HashSet<>(src).size());
        q("tree", new TreeSet<>(src).size());
        q("deque", new ArrayDeque<>(src).size());
        q("linked", new LinkedList<>(src).size());
        q("nested", new ArrayList<>(Arrays.asList("x")).size());
        r("str", new ArrayList<>(src).toString());
        r("first", new ArrayList<>(src).get(0));
        System.out.println("end");
    }
}
"#
);

// A METHOD REFERENCE is a functional-interface expression wherever a lambda is.
// These were refused with the false claim that the position is not one.
differential_test!(
    diff_method_ref_to_collection_consumers,
    "DiffMethodRefEach",
    r#"
import java.util.*;
public class DiffMethodRefEach {
    static void p(String s) { System.out.println("p:" + s); }
    static boolean isX(String s) { return s.equals("x"); }
    public static void main(String[] args) {
        List<String> l = new ArrayList<>(Arrays.asList("x", "y"));
        l.forEach(DiffMethodRefEach::p);
        l.forEach(System.out::println);
        Iterator<String> it = l.iterator();
        it.forEachRemaining(DiffMethodRefEach::p);
        List<String> m = new ArrayList<>(Arrays.asList("x", "y"));
        m.removeIf(DiffMethodRefEach::isX);
        System.out.println(m);
        m.replaceAll(String::toUpperCase);
        System.out.println(m);
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-9 cluster: constant expressions (JLS §15.29) and constant variables
// (§4.12.4).
// ---------------------------------------------------------------------------

// A `final` variable initialized with a constant EXPRESSION is a constant
// variable, and its reads are inlined. caturra recognised only bare literals, so
// a `static final int MODE = 1 + 1;` was not one — and three separate rules key
// off that: case labels, class initialization, and reachability.
differential_test!(
    diff_constant_expressions,
    "DiffConstExpr",
    r#"
class ConstHolder {
    static { System.out.println("HOLDER INIT"); }
    static final String S = "a" + "b";
    static final char C = (char) 65;
    static final int N = 2 * 3 + 1;
    static final boolean B = true && false;
    static final double D = 1.0 / 2;
    static final long L = 1L << 40;
    static final int M = Integer.MAX_VALUE;
    static final int SHIFTED = -8 >>> 28;
}
public class DiffConstExpr {
    static final int MODE = 1 + 1;
    static final String J = "j" + "b";
    public static void main(String[] args) {
        // Reading a constant variable does NOT initialize its class.
        System.out.println(ConstHolder.S + " " + ConstHolder.C + " " + ConstHolder.N);
        System.out.println(ConstHolder.B + " " + ConstHolder.D + " " + ConstHolder.L);
        System.out.println(ConstHolder.M + " " + ConstHolder.SHIFTED);
        switch (2) {
            case MODE: System.out.println("mode"); break;
            default: System.out.println("no");
        }
        switch ("jb") {
            case J: System.out.println("J"); break;
            default: System.out.println("no");
        }
        int x = Integer.MIN_VALUE;
        switch (x) {
            case Integer.MIN_VALUE: System.out.println("min"); break;
            default: System.out.println("no");
        }
        switch (1) {
            case (int) 1L: System.out.println("cast"); break;
            default: System.out.println("no");
        }
        switch ("y") {
            case true ? "y" : "n": System.out.println("ternary"); break;
            default: System.out.println("no");
        }
        switch ("b") {
            case (String) "b": System.out.println("strcast"); break;
            default: System.out.println("no");
        }
        switch (ConstHolder.C) {
            case 'A': System.out.println("charconst"); break;
            default: System.out.println("no");
        }
    }
}
"#
);

// javac: a `while` over a false constant makes its body unreachable — including
// a constant declared in ANOTHER class, which the flow pass could not see.
differential_wording!(
    reject_unreachable_over_other_class_constant,
    "RejectUnreachableConst",
    r#"
class Cfg {
    static final boolean DEBUG = false;
}
public class RejectUnreachableConst {
    public static void main(String[] args) {
        if (Cfg.DEBUG) { System.out.println("never"); }
        while (Cfg.DEBUG) { System.out.println("never2"); }
        System.out.println("end");
    }
}
"#
);

// javac: a case label of the wrong TYPE is a type error naming both types, not
// a complaint about constness.
differential_wording!(
    reject_case_label_type_mismatch,
    "RejectLabelType",
    r#"
public class RejectLabelType {
    public static void main(String[] args) {
        String s = "a";
        switch (s) {
            case 'a': System.out.println("charlabel"); break;
            default: System.out.println("d");
        }
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-9 cluster: format conversions (java.util.Formatter).
// ---------------------------------------------------------------------------

// The classic logging helper — a varargs RELAY — formatted every heap object as
// the EMPTY STRING. The compiler coerces a directly-written argument to text at
// the call site; an argument arriving through an `Object...` array has no static
// type left to coerce, and the formatter (which sees only the heap) cannot call
// a user `toString()`. The VM now renders them before formatting.
differential_test!(
    diff_format_object_relay,
    "DiffFormatRelay",
    r#"
import java.util.*;
public class DiffFormatRelay {
    enum Day { MON }
    static class Point { public String toString() { return "(1,2)"; } }
    static void log(String fmt, Object... a) {
        System.out.println("log -> " + String.format(fmt, a));
    }
    public static void main(String[] args) {
        log("enum=%s", Day.MON);
        log("obj=%s", new Point());
        ArrayList<Integer> list = new ArrayList<>();
        list.add(9);
        log("list=%s", list);
        log("sb=%s", new StringBuilder("q"));
        log("map=%s", new TreeMap<>(Collections.singletonMap("k", 1)));
        log("str=%s int=%d boxed=%d", "ok", 5, Integer.valueOf(7));
        log("null=%s bool=%b", null, null);
        Object[] arr = new Object[] { Day.MON, new Point() };
        System.out.println("array -> " + String.format("%s %s", arr));
        System.out.printf("printf -> %s %s%n", Day.MON, new Point());
        int[] ints = { 1, 2 };
        System.out.println("prim -> " + String.format("%s", ints).startsWith("[I@"));
        System.out.println("class -> " + String.format("%s|%s", String.class, int.class));
    }
}
"#
);

// The specifier grammar and the run-time validations, each recorded from a real
// JDK: an out-of-range width is IGNORED (not clamped, which built a
// 2-billion-character string), a '.' with no digits ENDS the specifier and is
// reported against the character after the '%', ',' is illegal for the
// scientific conversions (reported with the LOWERCASE conversion), `%n`/`%%`
// take no flags, and a null argument ARRAY answers null for every specifier.
differential_test!(
    diff_format_specifier_rules,
    "DiffFormatRules",
    r#"
public class DiffFormatRules {
    static void t(String label, String fmt, Object... a) {
        try {
            System.out.println(label + " OK [" + String.format(fmt, a).replace("\n", "\\n") + "]");
        } catch (Exception e) {
            System.out.println(label + " EX " + e.getClass().getName() + ": " + e.getMessage());
        }
    }
    public static void main(String[] args) {
        String wide = String.format("%2147483648d", 1);
        System.out.println("width length=" + wide.length() + " [" + wide.trim() + "]");
        t("comma-e", "%,e", 12345.0);
        t("comma-E", "%,E", 12345.0);
        t("comma-S", "%,S", "hi");
        t("hash-g", "%#g", 12345.0);
        t("dot-f", "%.f", 1.5);
        t("dot-s", "%.s", "hi");
        t("dot-d", "%.d", 1);
        t("w-dot-d", "%5.d", 1);
        t("q", "%q", 1);
        t("w-q", "%5q", 1);
        t("plus-pct", "%+%");
        t("minus-n", "%-n");
        t("prec-n", "%.2n");
        t("width-n", "%5n");
        System.out.println("[" + String.format("%s", (Object[]) null) + "]");
        System.out.println("[" + String.format("%s %s", (Object[]) null) + "]");
        System.out.println("[" + String.format("%2$s", (Object[]) null) + "]");
        try {
            System.out.println(String.format((String) null, 1));
        } catch (Exception e) {
            System.out.println("null-fmt " + e.getClass().getName() + " msg=" + e.getMessage());
        }
    }
}
"#
);

// `Locale.US` (and its synonyms) name the locale caturra always formats in, so
// the argument is accepted and dropped rather than the class being reported as
// nonexistent.
differential_test!(
    diff_format_us_locale,
    "DiffFormatLocale",
    r#"
import java.util.Locale;
public class DiffFormatLocale {
    public static void main(String[] args) {
        System.out.println(String.format(Locale.US, "[%,.2f]", 1234567.891));
        System.out.println(String.format(Locale.US, "[%,d]", 1234567));
        System.out.printf(Locale.ROOT, "[%,d]%n", 987654);
    }
}
"#
);

// A DIAMOND constructor passed to a varargs parameter. caturra types a diamond
// whose element it cannot infer as `Null`, and `null` IS assignable to the
// varargs array — so the object itself was passed where the array belonged, and
// the callee saw a TreeMap in place of its `Object[]`. Only a real null (the
// literal, or a cast of one) takes the array form.
differential_test!(
    diff_varargs_diamond_argument,
    "DiffVarargsDiamond",
    r#"
import java.util.*;
public class DiffVarargsDiamond {
    static void log(String fmt, Object... a) { System.out.println("log " + a.length + " -> " + String.format(fmt, a)); }
    static int count(Object... a) { return a == null ? -1 : a.length; }
    public static void main(String[] args) {
        Map<String, Integer> m = new TreeMap<>();
        m.put("k", 1);
        log("A=%s", new TreeMap<>(m));
        log("B=%s", new ArrayList<>(Arrays.asList("x")));
        log("C=%s", new HashSet<>(Arrays.asList("y")));
        log("none");
        System.out.println(count());
        System.out.println(count("a", "b"));
        System.out.println(count((Object[]) null));
        System.out.println(count(new Object[] { 1, 2, 3 }));
    }
}
"#
);

// A map COPY constructor over any map-shaped source. Only a real HashMap was
// understood, so an immutable view was a ClassCastException into a HashMap and
// silently NOTHING into a TreeMap — an empty map where the JDK gives the copy.
differential_test!(
    diff_map_copy_constructors,
    "DiffMapCopy",
    r#"
import java.util.*;
public class DiffMapCopy {
    public static void main(String[] args) {
        Map<String, Integer> src = new HashMap<>();
        src.put("k", 1);
        src.put("j", 2);
        System.out.println(new HashMap<>(src));
        System.out.println(new TreeMap<>(src));
        System.out.println(new HashMap<>(new TreeMap<>(src)));
        System.out.println(new TreeMap<>(Collections.singletonMap("z", 9)));
        System.out.println(new HashMap<>(Collections.singletonMap("z", 9)));
        System.out.println(new HashMap<>(Collections.unmodifiableMap(src)));
        TreeMap<String, Integer> t = new TreeMap<>(src);
        System.out.println(t.firstKey() + " " + t.size());
    }
}
"#
);

// ---------------------------------------------------------------------------
// Round-9 cluster: catch and Throwable semantics (JLS §11, §14.20).
// ---------------------------------------------------------------------------

// A cause is set ONCE, an exception cannot suppress itself, a
// `getLocalizedMessage()` with no override IS `getMessage()` (so an overridden
// one answers for it), and `super.getMessage()`/`super.toString()` inside a user
// exception reach Throwable's own behaviour — the last did not compile at all.
differential_test!(
    diff_throwable_contract,
    "DiffThrowable",
    r#"
class DiffEx extends RuntimeException {
    DiffEx(String m) { super(m); }
    @Override public String getMessage() { return "<" + super.getMessage() + ">"; }
    @Override public String toString() { return "[" + super.toString() + "]"; }
}
public class DiffThrowable {
    public static void main(String[] args) {
        try { throw new DiffEx("hi"); }
        catch (RuntimeException e) {
            System.out.println(e);
            System.out.println(e.getMessage());
            System.out.println(e.getLocalizedMessage());
        }
        RuntimeException a = new RuntimeException("a");
        RuntimeException b = new RuntimeException("b");
        RuntimeException c = new RuntimeException("c");
        c.initCause(a);
        System.out.println("cause=" + c.getCause().getMessage());
        try { c.initCause(b); }
        catch (IllegalStateException e) { System.out.println("ISE " + e.getMessage()); }
        System.out.println("still=" + c.getCause().getMessage());
        try { a.addSuppressed(a); }
        catch (IllegalArgumentException e) { System.out.println("IAE " + e.getMessage()); }
        try { a.addSuppressed(null); }
        catch (NullPointerException e) { System.out.println("NPE " + e.getMessage()); }
        System.out.println("sup=" + a.getSuppressed().length);
    }
}
"#
);

// A multi-catch parameter's static type is the least upper bound of the
// alternatives, so the methods their common superclass declares are callable.
// Typing it as `Throwable` refused every one of them.
differential_test!(
    diff_multi_catch_lub,
    "DiffMultiCatch",
    r#"
public class DiffMultiCatch {
    static class Base extends RuntimeException {
        Base(String m) { super(m); }
        int tag() { return 0; }
    }
    static class A extends Base { A(String m) { super(m); } int tag() { return 1; } }
    static class B extends Base { B(String m) { super(m); } int tag() { return 2; } }
    public static void main(String[] args) {
        for (int k = 0; k < 2; k++) {
            try {
                if (k == 0) throw new A("a"); else throw new B("b");
            } catch (A | B e) {
                System.out.println("tag=" + e.tag() + " msg=" + e.getMessage());
            }
        }
    }
}
"#
);

// javac: precise rethrow requires an effectively final catch parameter. Assigned,
// `throw e` throws the parameter's DECLARED type, which this method does not
// report.
differential_wording!(
    reject_rethrow_of_assigned_parameter,
    "RejectRethrow",
    r#"
public class RejectRethrow {
    static class A extends Exception {}
    static class B extends Exception {}
    static void g(int k) throws A, B { if (k == 0) throw new A(); throw new B(); }
    static void f(int k) throws A, B {
        try {
            g(k);
        } catch (Exception e) {
            e = new Exception("re");
            throw e;
        }
    }
    public static void main(String[] args) throws Exception { f(0); }
}
"#
);

