differential_test!(
    big_integer_arithmetic_is_exact,
    "BigArith",
    r#"
import java.math.BigInteger;

public class BigArith {
    static void probe(String label, java.util.function.Supplier<Object> body) {
        try {
            System.out.println(label + " = " + body.get());
        } catch (Throwable e) {
            System.out.println(label + " ! " + e.getClass().getName() + ": " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        BigInteger big = new BigInteger("12345678901234567890");
        BigInteger neg = new BigInteger("-98765432109876543210");
        BigInteger small = BigInteger.valueOf(7);
        probe("add", () -> big.add(neg));
        probe("subtract", () -> big.subtract(neg));
        probe("multiply", () -> big.multiply(neg));
        probe("divide", () -> neg.divide(big));
        probe("remainder", () -> neg.remainder(big));
        probe("mod", () -> neg.mod(big));
        probe("mod of a negative modulus", () -> big.mod(neg));
        probe("divide by zero", () -> big.divide(BigInteger.ZERO));
        probe("divideAndRemainder", () -> java.util.Arrays.toString(neg.divideAndRemainder(small)));
        probe("gcd", () -> big.gcd(neg));
        probe("pow", () -> small.pow(30));
        probe("negative exponent", () -> small.pow(-1));
        probe("sqrt", () -> big.multiply(big).sqrt());
        probe("sqrt of a negative", () -> neg.sqrt());
        probe("modPow", () -> small.modPow(BigInteger.valueOf(128), BigInteger.valueOf(13)));
        probe("modInverse", () -> BigInteger.valueOf(3).modInverse(BigInteger.valueOf(11)));
        probe("no inverse", () -> BigInteger.valueOf(4).modInverse(BigInteger.valueOf(8)));
        probe("compareTo", () -> big.compareTo(neg) + " " + neg.compareTo(big) + " " + big.compareTo(big));
        probe("equals and hash", () -> big.equals(new BigInteger("12345678901234567890"))
            + " " + big.hashCode() + " " + neg.hashCode());
        probe("min and max", () -> big.min(neg) + " " + big.max(neg));
        BigInteger factorial = BigInteger.ONE;
        for (int i = 1; i <= 40; i++) {
            factorial = factorial.multiply(BigInteger.valueOf(i));
        }
        System.out.println("40! = " + factorial);
        System.out.println("constants = " + BigInteger.ZERO + " " + BigInteger.ONE
            + " " + BigInteger.TWO + " " + BigInteger.TEN);
    }
}
"#
);

differential_test!(
    big_integer_bits_and_conversions,
    "BigBits",
    r#"
import java.math.BigInteger;

public class BigBits {
    static void probe(String label, java.util.function.Supplier<Object> body) {
        try {
            System.out.println(label + " = " + body.get());
        } catch (Throwable e) {
            System.out.println(label + " ! " + e.getClass().getName() + ": " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        BigInteger big = new BigInteger("18446744073709551616");
        BigInteger neg = BigInteger.valueOf(-7);
        // A negative value's bits are its INFINITE two's complement, which is
        // not the magnitude's: -7 is ...11111001.
        probe("bitLength", () -> neg.bitLength() + " " + big.bitLength()
            + " " + BigInteger.valueOf(-1).bitLength() + " " + BigInteger.ZERO.bitLength());
        probe("bitCount", () -> neg.bitCount() + " " + big.bitCount()
            + " " + BigInteger.valueOf(-1).bitCount() + " " + BigInteger.valueOf(255).bitCount());
        probe("testBit", () -> neg.testBit(0) + " " + neg.testBit(1) + " " + neg.testBit(64)
            + " " + big.testBit(64));
        probe("lowest set bit", () -> BigInteger.valueOf(12).getLowestSetBit()
            + " " + BigInteger.ZERO.getLowestSetBit());
        probe("negative bit address", () -> neg.testBit(-1));
        probe("shifts", () -> neg.shiftLeft(5) + " " + neg.shiftRight(1)
            + " " + big.shiftRight(64) + " " + neg.shiftLeft(-2));
        probe("and or xor not", () -> BigInteger.valueOf(12).and(BigInteger.TEN)
            + " " + BigInteger.valueOf(12).or(BigInteger.TEN)
            + " " + BigInteger.valueOf(12).xor(BigInteger.TEN)
            + " " + BigInteger.valueOf(12).not()
            + " " + BigInteger.valueOf(12).andNot(BigInteger.valueOf(3)));
        probe("set clear flip", () -> neg.setBit(4) + " " + neg.clearBit(1) + " " + neg.flipBit(0));
        // The narrowing reads TRUNCATE; the exact ones refuse, each naming its
        // own width.
        probe("narrowing", () -> big.intValue() + " " + big.longValue()
            + " " + big.shortValue() + " " + big.byteValue());
        probe("floating", () -> big.doubleValue() + " " + big.floatValue()
            + " " + new BigInteger("1" + "0".repeat(400)).doubleValue());
        probe("intValueExact", () -> BigInteger.valueOf(5).intValueExact());
        probe("intValueExact refused", () -> big.intValueExact());
        probe("longValueExact refused", () -> big.longValueExact());
        probe("shortValueExact refused", () -> BigInteger.valueOf(99999).shortValueExact());
        probe("byteValueExact refused", () -> BigInteger.valueOf(999).byteValueExact());
        probe("primes", () -> BigInteger.valueOf(7).isProbablePrime(20)
            + " " + BigInteger.valueOf(9).isProbablePrime(20)
            + " " + BigInteger.valueOf(7).nextProbablePrime()
            + " " + new BigInteger("1000000000000").nextProbablePrime());
        probe("radix", () -> neg.toString(2) + " " + big.toString(16) + " " + big.toString(36)
            + " " + neg.toString(37));
    }
}
"#
);

differential_test!(
    big_integer_text_and_formatting,
    "BigText",
    r#"
import java.math.BigInteger;

public class BigText {
    static void probe(String label, java.util.function.Supplier<Object> body) {
        try {
            System.out.println(label + " = " + body.get());
        } catch (Throwable e) {
            System.out.println(label + " ! " + e.getClass().getName() + ": " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // The four refusals a JDK's parser has, which say four different things.
        probe("plain", () -> new BigInteger("000123"));
        probe("plus sign", () -> new BigInteger("+42"));
        probe("radix", () -> new BigInteger("ff", 16) + " " + new BigInteger("-1010", 2));
        probe("bad digit", () -> new BigInteger("12x"));
        probe("bad digit after a sign", () -> new BigInteger("-1a"));
        probe("bad digit in a radix", () -> new BigInteger("xyz", 16));
        probe("empty", () -> new BigInteger(""));
        probe("a sign alone", () -> new BigInteger("-"));
        probe("two signs", () -> new BigInteger("--5"));
        probe("a sign at the end", () -> new BigInteger("5-"));
        probe("leading space", () -> new BigInteger(" 5"));
        probe("radix out of range", () -> new BigInteger("10", 1));
        BigInteger neg = new BigInteger("-255");
        BigInteger pos = new BigInteger("255");
        // A `BigInteger` prints in SIGN-MAGNITUDE under %x and %o, unlike an
        // int's two's complement, so the signed flags mean something there.
        probe("d", () -> String.format("[%d][%,d][%+d][%(d][% d][%08d][%-8d]",
            neg, new BigInteger("1234567"), pos, neg, pos, neg, neg));
        probe("x and o", () -> String.format("[%x][%X][%o][%+x][%(x][%#x][%#o][%08x]",
            neg, neg, neg, pos, neg, neg, neg, neg));
        probe("s and h", () -> String.format("[%s][%S][%10s][%b][%h]", neg, neg, neg, neg, neg));
        probe("the alternate flag on a d", () -> String.format("%#d", pos));
        probe("grouping on an x", () -> String.format("%,x", pos));
        probe("a float conversion", () -> String.format("%e", pos));
        probe("concatenation", () -> "n=" + pos);
    }
}
"#
);

differential_test!(
    a_big_integer_in_every_position,
    "BigWhere",
    r#"
import java.math.BigInteger;
import java.util.*;
import java.util.stream.*;

public class BigWhere {
    static BigInteger field = BigInteger.ONE;
    static BigInteger doubled(BigInteger n) { return n.multiply(BigInteger.TWO); }
    static <T extends Comparable<T>> T biggest(List<T> items) { return Collections.max(items); }
    static class Box<T> { T held; Box(T held) { this.held = held; } T get() { return held; } }

    public static void main(String[] args) {
        BigInteger a = new BigInteger("123456789012345678901234567890");
        BigInteger b = BigInteger.valueOf(97);
        System.out.println(field + " " + doubled(a));
        BigInteger[] arr = { a, b, BigInteger.ZERO };
        Arrays.sort(arr);
        System.out.println(Arrays.toString(arr));
        List<BigInteger> list = new ArrayList<>(Arrays.asList(arr));
        System.out.println(list.contains(b) + " " + list.indexOf(b));
        Map<String, BigInteger> map = new HashMap<>();
        map.put("a", a);
        System.out.println(map.get("a").mod(b));
        TreeMap<BigInteger, String> tree = new TreeMap<>();
        tree.put(b, "small");
        tree.put(a, "big");
        System.out.println(tree.firstKey() + " " + tree.lastEntry().getValue());
        System.out.println(new TreeSet<>(list));
        Object o = a;
        System.out.println((o instanceof BigInteger) + " " + ((BigInteger) o).equals(a));
        System.out.println(biggest(list) + " " + new Box<>(a).get().bitLength());
        System.out.println(list.stream().map(BigInteger::toString).collect(Collectors.joining("/")));
        System.out.println(list.stream().reduce(BigInteger.ZERO, BigInteger::add));
        System.out.println(list.stream().mapToInt(BigInteger::signum).sum());
        list.sort(Comparator.comparing(BigInteger::bitLength));
        System.out.println(list);
        for (BigInteger each : list) {
            System.out.print(each.signum());
        }
        System.out.println();
        StringBuilder sb = new StringBuilder();
        sb.append(a).append('|').append(b);
        System.out.println(sb);
        System.out.println(Objects.equals(a, new BigInteger("123456789012345678901234567890"))
            + " " + Objects.hash(b) + " " + b.hashCode());
        System.out.println(list.get(0).getClass().getSimpleName()
            + " " + list.get(0).getClass().getName());
        System.out.println(list.stream().collect(Collectors.partitioningBy(x -> x.testBit(0))));
        System.out.println(Stream.of(a, b).max(Comparator.naturalOrder()).get());
        Number n = a;
        Comparable<BigInteger> c = b;
        System.out.println(n.longValue() + " " + c.compareTo(a));
        System.out.println(new HashSet<>(List.of(b, BigInteger.valueOf(97))).size());
    }
}
"#
);

differential_test!(
    a_big_decimal_in_every_position,
    "BQ",
    r#"
import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.util.*;
import java.util.stream.*;

public class BQ {
  static BigDecimal rate = new BigDecimal("0.0825");
  static RoundingMode mode = RoundingMode.HALF_UP;
  static BigDecimal withTax(BigDecimal price) { return price.multiply(BigDecimal.ONE.add(rate)).setScale(2, mode); }
  static <T extends Comparable<T>> T biggest(List<T> items) { return Collections.max(items); }
  static class Box<T> { T held; Box(T held) { this.held = held; } T get() { return held; } }
  static String describe(RoundingMode m) { switch (m) { case FLOOR: return "down"; case CEILING: return "up"; default: return m.name(); } }

  public static void main(String[] args) {
    BigDecimal price = new BigDecimal("19.99");
    System.out.println(withTax(price) + " " + rate.scale() + " " + rate.precision());
    BigDecimal[] cart = { price, new BigDecimal("4.50"), new BigDecimal("100") };
    System.out.println(Arrays.toString(cart));
    Arrays.sort(cart);
    System.out.println(Arrays.toString(cart));
    List<BigDecimal> list = new ArrayList<>(Arrays.asList(cart));
    System.out.println(list.contains(price) + " " + list.indexOf(price));
    BigDecimal total = BigDecimal.ZERO;
    for (BigDecimal item : list) { total = total.add(item); }
    System.out.println(total + " " + total.setScale(2, RoundingMode.HALF_EVEN));
    Map<String, BigDecimal> prices = new HashMap<>();
    prices.put("book", price);
    System.out.println(prices.get("book").multiply(new BigDecimal("3")));
    TreeMap<BigDecimal, String> byPrice = new TreeMap<>();
    byPrice.put(price, "book"); byPrice.put(new BigDecimal("4.50"), "pen");
    System.out.println(byPrice.firstKey() + " " + byPrice.lastEntry().getValue());
    System.out.println(new TreeSet<>(list));
    Object o = price;
    System.out.println((o instanceof BigDecimal) + " " + ((BigDecimal) o).equals(price));
    System.out.println(biggest(list) + " " + new Box<>(price).get().scale());
    System.out.println(list.stream().map(BigDecimal::toPlainString).collect(Collectors.joining("+")));
    System.out.println(list.stream().reduce(BigDecimal.ZERO, BigDecimal::add));
    System.out.println(list.stream().mapToInt(BigDecimal::signum).sum());
    list.sort(Comparator.comparing(BigDecimal::scale).thenComparing(Comparator.naturalOrder()));
    System.out.println(list);
    System.out.println(Stream.of(cart).max(Comparator.naturalOrder()).get());
    StringBuilder sb = new StringBuilder();
    sb.append(price).append('|').append(mode);
    System.out.println(sb);
    System.out.println(Objects.equals(price, new BigDecimal("19.99")) + " " + price.hashCode());
    System.out.println(price.getClass().getSimpleName() + " " + price.getClass().getName());
    Number n = price;
    Comparable<BigDecimal> c = price;
    System.out.println(n.doubleValue() + " " + c.compareTo(BigDecimal.TEN));
    // A RoundingMode is a real enum: it switches, it fills an EnumSet, and it streams.
    System.out.println(describe(RoundingMode.FLOOR) + " " + describe(RoundingMode.UP));
    System.out.println(EnumSet.of(RoundingMode.UP, RoundingMode.FLOOR));
    System.out.println(Arrays.stream(RoundingMode.values()).map(RoundingMode::name).collect(Collectors.toList()));
    System.out.println(Arrays.stream(RoundingMode.values()).filter(m -> m.name().startsWith("HALF")).count());
    EnumMap<RoundingMode, BigDecimal> rounded = new EnumMap<>(RoundingMode.class);
    for (RoundingMode m : RoundingMode.values()) {
      if (m != RoundingMode.UNNECESSARY) { rounded.put(m, new BigDecimal("2.5").setScale(0, m)); }
    }
    System.out.println(rounded);
    MathContext five = new MathContext(5);
    System.out.println(BigDecimal.ONE.divide(new BigDecimal("7"), five) + " " + five + " " + five.getPrecision());
    System.out.println(new BigDecimal("1234.5678").round(MathContext.DECIMAL32));
    List<RoundingMode> modes = new ArrayList<>(List.of(RoundingMode.HALF_UP, RoundingMode.UP));
    Collections.sort(modes);
    System.out.println(modes + " " + modes.get(0).ordinal());
    System.out.println(String.format("%.2f %,.2f %e %s %g", price, new BigDecimal("1234567.891"), price, price, price));
  }
}
"#
);

differential_test!(
    big_decimal_keeps_its_scale,
    "DecScale",
    r#"
import java.math.BigDecimal;
import java.math.RoundingMode;

public class DecScale {
    static void probe(String label, java.util.function.Supplier<Object> body) {
        try {
            System.out.println(label + " = " + body.get());
        } catch (Throwable e) {
            System.out.println(label + " ! " + e.getClass().getName() + ": " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // The scale is OBSERVABLE, which is the whole difference from double.
        probe("equals is not compareTo", () -> new BigDecimal("2.0").equals(new BigDecimal("2.00"))
            + " " + new BigDecimal("2.0").compareTo(new BigDecimal("2.00"))
            + " " + new BigDecimal("2.0").hashCode() + " " + new BigDecimal("2.00").hashCode());
        probe("in a set", () -> new java.util.HashSet<>(java.util.List.of(
            new BigDecimal("2.0"), new BigDecimal("2.00"))).size());
        probe("the classic", () -> new BigDecimal("0.1").add(new BigDecimal("0.2"))
            + " vs " + (0.1 + 0.2));
        probe("scales add", () -> new BigDecimal("2.50").multiply(new BigDecimal("4.000"))
            + " " + new BigDecimal("2.5").add(new BigDecimal("0.001"))
            + " " + new BigDecimal("1E+3").add(BigDecimal.ONE));
        probe("exact division", () -> new BigDecimal("2.50").divide(BigDecimal.ONE)
            + " " + new BigDecimal("10").divide(new BigDecimal("4"))
            + " " + new BigDecimal("100").divide(new BigDecimal("5"))
            + " " + new BigDecimal("1.00").divide(new BigDecimal("4.0")));
        probe("non-terminating", () -> BigDecimal.ONE.divide(new BigDecimal("3")));
        probe("divide by zero", () -> BigDecimal.ONE.divide(BigDecimal.ZERO));
        probe("zero over zero", () -> BigDecimal.ZERO.divide(BigDecimal.ZERO));
        probe("divide at a scale", () -> BigDecimal.ONE.divide(new BigDecimal("3"), 4, RoundingMode.HALF_UP)
            + " " + new BigDecimal("10").divide(new BigDecimal("3"), RoundingMode.HALF_UP)
            + " " + new BigDecimal("10.00").divide(new BigDecimal("3"), RoundingMode.HALF_UP));
        probe("divide at a scale by zero", () -> BigDecimal.ONE.divide(BigDecimal.ZERO, 2, RoundingMode.HALF_UP));
        probe("integral and remainder", () -> new BigDecimal("7.5").divideToIntegralValue(new BigDecimal("2"))
            + " " + new BigDecimal("7.5").remainder(new BigDecimal("2"))
            + " " + java.util.Arrays.toString(new BigDecimal("7.5").divideAndRemainder(new BigDecimal("2")))
            + " " + new BigDecimal("-7").remainder(new BigDecimal("5")));
        // Every rounding mode, at the tie a half sits on.
        for (RoundingMode mode : RoundingMode.values()) {
            final RoundingMode m = mode;
            probe("2.5 " + m, () -> new BigDecimal("2.5").setScale(0, m)
                + " " + new BigDecimal("3.5").setScale(0, m)
                + " " + new BigDecimal("-2.5").setScale(0, m));
        }
        probe("setScale bare", () -> new BigDecimal("2.5").setScale(3) + " " + new BigDecimal("1E+3").setScale(1));
        probe("setScale loses", () -> new BigDecimal("2.55").setScale(1));
        probe("deprecated int mode", () -> new BigDecimal("2.55").setScale(1, BigDecimal.ROUND_HALF_UP)
            + " " + new BigDecimal("10").divide(new BigDecimal("3"), 4, BigDecimal.ROUND_HALF_UP));
        probe("pow", () -> new BigDecimal("2.5").pow(3) + " " + new BigDecimal("2.5").pow(0));
        probe("negative exponent", () -> new BigDecimal("2.5").pow(-1));
        probe("the three texts", () -> new BigDecimal("1E+3") + " / " + new BigDecimal("1E+3").toPlainString()
            + " / " + new BigDecimal("1E+3").toEngineeringString()
            + " | " + new BigDecimal("1E-7") + " / " + new BigDecimal("1E-7").toPlainString()
            + " / " + new BigDecimal("1E-7").toEngineeringString()
            + " | " + new BigDecimal("3E+1").toEngineeringString()
            + " | " + new BigDecimal("0E+1").toEngineeringString());
        probe("no negative zero", () -> new BigDecimal("-0.0") + " " + new BigDecimal("-0.000003").setScale(5, RoundingMode.DOWN));
        probe("stripTrailingZeros", () -> new BigDecimal("600.0").stripTrailingZeros()
            + " " + new BigDecimal("600").stripTrailingZeros() + " " + new BigDecimal("0.000").stripTrailingZeros());
        probe("moving the point", () -> new BigDecimal("2.50").movePointLeft(5)
            + " " + new BigDecimal("2.50").movePointRight(5)
            + " " + new BigDecimal("2.50").scaleByPowerOfTen(5)
            + " " + new BigDecimal("0.0").scaleByPowerOfTen(5));
        probe("parts", () -> new BigDecimal("0.00").scale() + " " + new BigDecimal("0.00").precision()
            + " " + new BigDecimal("0.00").unscaledValue() + " " + new BigDecimal("1E+3").scale()
            + " " + new BigDecimal("2.50").ulp());
        probe("reading numbers", () -> new BigDecimal("-2.9").intValue() + " " + new BigDecimal("1E+3").intValue()
            + " " + new BigDecimal("0.1").doubleValue() + " " + new BigDecimal("0.1").floatValue()
            + " " + new BigDecimal("1E+400").doubleValue() + " " + new BigDecimal("2.50").toBigInteger());
        probe("exact reads", () -> new BigDecimal("2.00").intValueExact());
        probe("a fraction is not exact", () -> new BigDecimal("2.01").intValueExact());
        probe("too wide to be exact", () -> new BigDecimal("1E+30").longValueExact());
        probe("toBigIntegerExact", () -> new BigDecimal("2.50").toBigIntegerExact());
        // The two ways a double becomes a decimal, which do not agree.
        probe("from a double", () -> new BigDecimal(0.1) + " | " + BigDecimal.valueOf(0.1)
            + " " + BigDecimal.valueOf(2.50) + " " + BigDecimal.valueOf(12345, 2));
        probe("parse refusals", () -> new BigDecimal("1.2.3"));
        probe("empty", () -> new BigDecimal(""));
        probe("a space", () -> new BigDecimal(" 1"));
        probe("money", () -> new BigDecimal("19.99").multiply(new BigDecimal("3")).setScale(2, RoundingMode.HALF_UP));
    }
}
"#
);

differential_test!(
    big_decimal_formats_exactly,
    "DecFormat",
    r#"
import java.math.BigDecimal;

public class DecFormat {
    static void probe(String label, java.util.function.Supplier<Object> body) {
        try {
            System.out.println(label + " = " + body.get());
        } catch (Throwable e) {
            System.out.println(label + " ! " + e.getClass().getName() + ": " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        BigDecimal value = new BigDecimal("1234.5");
        BigDecimal small = new BigDecimal("-0.005");
        // A decimal reaches the float conversions with its OWN digits, so one
        // a double could not hold prints every one of them.
        BigDecimal huge = new BigDecimal("123456789012345678901234567890.125");
        for (String shape : new String[] {
            "%s", "%S", "%12s", "%f", "%.2f", "%,.3f", "%10.1f", "%+f", "%(f",
            "%08.2f", "%-10.2f", "%e", "%.3e", "%E", "%g", "%.4g", "%b", "%h",
            "%a", "%d", "%x", "%o", "%c",
        }) {
            final String spec = shape;
            probe("value " + spec, () -> "[" + String.format(spec, value) + "]");
            probe("small " + spec, () -> "[" + String.format(spec, small) + "]");
            probe("huge " + spec, () -> "[" + String.format(spec, huge) + "]");
        }
        probe("zero", () -> String.format("[%f][%e][%g][%.0f]", BigDecimal.ZERO, BigDecimal.ZERO,
            BigDecimal.ZERO, BigDecimal.ZERO));
        probe("concatenation", () -> "n=" + value + " " + small);
    }
}
"#
);

differential_test!(
    a_number_format_in_every_position,
    "DQ",
    r##"
import java.text.DecimalFormat;
import java.text.NumberFormat;
import java.text.ParseException;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import java.util.stream.*;

public class DQ {
  static final DecimalFormat MONEY = new DecimalFormat("#,##0.00");
  static NumberFormat percent = NumberFormat.getPercentInstance();
  static String bill(double amount) { return MONEY.format(amount); }

  public static void main(String[] args) throws ParseException {
    System.out.println(bill(1234.5) + " " + percent.format(0.756));
    NumberFormat plain = NumberFormat.getInstance();
    NumberFormat whole = NumberFormat.getIntegerInstance();
    NumberFormat money = NumberFormat.getCurrencyInstance();
    System.out.println(plain.format(1234.5678) + " " + whole.format(1234.5678) + " " + money.format(-5));
    // A DecimalFormat IS a NumberFormat.
    NumberFormat asBase = MONEY;
    System.out.println(asBase.format(9.5) + " " + (asBase instanceof DecimalFormat));
    DecimalFormat back = (DecimalFormat) asBase;
    System.out.println(back.toPattern());
    // The limits a program changes after the fact.
    NumberFormat two = NumberFormat.getInstance();
    two.setMaximumFractionDigits(2);
    two.setMinimumFractionDigits(2);
    two.setGroupingUsed(false);
    System.out.println(two.format(1234.5) + " " + two.getMaximumFractionDigits() + two.isGroupingUsed());
    DecimalFormat rounded = new DecimalFormat("0.0");
    rounded.setRoundingMode(RoundingMode.FLOOR);
    System.out.println(rounded.format(2.55) + " " + rounded.getRoundingMode());
    rounded.applyPattern("0.000");
    System.out.println(rounded.format(2.5) + " " + rounded.getGroupingSize());
    // Reading numbers back.
    Number parsed = MONEY.parse("1,234.56");
    System.out.println(parsed + " " + parsed.intValue() + " " + parsed.doubleValue());
    System.out.println(new DecimalFormat("0").parse("42").getClass().getName());
    try {
      new DecimalFormat("0").parse("abc");
    } catch (ParseException e) {
      System.out.println("refused: " + e.getMessage());
    }
    try {
      new DecimalFormat("0.0.0");
    } catch (IllegalArgumentException e) {
      System.out.println("bad pattern: " + e.getMessage());
    }
    // In every position a value can take.
    DecimalFormat[] formats = { new DecimalFormat("0"), new DecimalFormat("0.00"), MONEY };
    System.out.println(Arrays.stream(formats).map(f -> f.format(3.14159)).collect(Collectors.joining("|")));
    List<NumberFormat> list = new ArrayList<>(Arrays.asList(formats));
    System.out.println(list.size() + " " + list.get(0).format(7));
    Map<String, NumberFormat> named = new HashMap<>();
    named.put("money", MONEY);
    System.out.println(named.get("money").format(19.995));
    Object o = MONEY;
    System.out.println(o.getClass().getName() + " " + (o instanceof NumberFormat));
    StringBuilder sb = new StringBuilder();
    sb.append(MONEY.format(1)).append('/').append(MONEY.format(2));
    System.out.println(sb);
    System.out.println(MONEY.equals(new DecimalFormat("#,##0.00")) + " " + MONEY.equals(new DecimalFormat("0")));
    // The formats a program actually writes.
    System.out.println(new DecimalFormat("#,##0.00").format(new BigDecimal("12345.678")));
    System.out.println(new DecimalFormat("0.###E0").format(12345.0));
    System.out.println(new DecimalFormat("#.##%").format(0.12345));
    System.out.println(new DecimalFormat("#,##0.00;(#,##0.00)").format(-42.5));
    for (double value : new double[] {0, 0.5, 2.5, 1.005, 99.995, 0.05, -0.5, 1e7}) {
      System.out.print(new DecimalFormat("0.00").format(value) + " ");
    }
    System.out.println();
  }
}
"##
);

differential_test!(
    where_a_number_parse_stops,
    "PS",
    r##"
import java.text.DecimalFormat;
import java.text.NumberFormat;
import java.math.BigDecimal;
public class PS {
  interface Body { Object get() throws Exception; }
  static void show(String l, Body b) {
    try {
      Object v = b.get();
      String kind = v == null ? "" : " (" + v.getClass().getSimpleName() + ")";
      String scale = v instanceof BigDecimal ? " scale=" + ((BigDecimal) v).scale() : "";
      System.out.println(l + " = " + v + kind + scale);
    }
    catch (Throwable e) { System.out.println(l + " ! " + e.getClass().getName() + ": " + e.getMessage()); }
  }
  public static void main(String[] a) {
    // A parse is a CURSOR: the prefix the pattern promised, then digits, then
    // the SUFFIX it promised. The suffix is not optional.
    String[] patterns = {"#,##0.00", "#", "#.##", "#%", "#‰", "#0.00;(#)",
                         "$#,##0.00;($#,##0.00)", "0.###E0", "#,##0;#,##0-", "+#;-#", "#u;#u",
                         "#;#", "0;#", "¤#0.00"};
    String[] texts = {"0", "7", "-7", "+7", "007", "12.75", ".75", "75.", "1,234", "1,2,3", ",5",
                      "12,", "1E3", "1E-3", "1E+3", "1e3", "1E", "1.5E2", "1E400", "1E-400",
                      "∞", "-∞", "NaN", "-NaN", "abc", "", " 7", "50%", "(12.50)",
                      "(12.50", "12.50)", "$12.50", "-$12.50", "9223372036854775807",
                      "-9223372036854775808", "9223372036854775808", "-0", "-0.0", "1.2,3", "1,.5",
                      "5-", "5u", "٥", "５", "1,234.56xyz"};
    for (String p : patterns) {
      for (String t : texts) {
        final String pp = p; final String tt = t;
        show("[" + pp + "] <" + tt + ">", () -> new DecimalFormat(pp).parse(tt));
        show("[" + pp + "]I <" + tt + ">", () -> {
          DecimalFormat f = new DecimalFormat(pp); f.setParseIntegerOnly(true); return f.parse(tt); });
        show("[" + pp + "]B <" + tt + ">", () -> {
          DecimalFormat f = new DecimalFormat(pp); f.setParseBigDecimal(true); return f.parse(tt); });
      }
    }
    // The multiplier divides what was read — and a NEGATIVE one flips the
    // sign, a ZERO one answers in double arithmetic rather than throwing.
    int[] multipliers = {1, 2, -2, 0, 100};
    String[] values = {"10", "-10", "5", "0", "-0", "∞", "-∞", "NaN", "99999999999999999999"};
    for (int m : multipliers) {
      for (String t : values) {
        final int mm = m; final String tt = t;
        show("x" + mm + " <" + tt + ">", () -> {
          DecimalFormat f = new DecimalFormat("#.##"); f.setMultiplier(mm); return f.parse(tt); });
        show("x" + mm + "I <" + tt + ">", () -> {
          DecimalFormat f = new DecimalFormat("#.##"); f.setMultiplier(mm);
          f.setParseIntegerOnly(true); return f.parse(tt); });
        show("x" + mm + "B <" + tt + ">", () -> {
          DecimalFormat f = new DecimalFormat("#.##"); f.setMultiplier(mm);
          f.setParseBigDecimal(true); return f.parse(tt); });
        show("x" + mm + " fmt <" + tt + ">", () -> {
          DecimalFormat f = new DecimalFormat("#.##"); f.setMultiplier(mm); return f.format(10); });
      }
    }
    // The sign a product wears, at the two edges a `long` has.
    show("min", () -> new DecimalFormat("#,##0.00").format(Long.MIN_VALUE));
    show("min x2", () -> { DecimalFormat f = new DecimalFormat("#"); f.setMultiplier(2); return f.format(Long.MIN_VALUE); });
    show("min int", () -> new DecimalFormat("#").format(Integer.MIN_VALUE));
    show("zero product", () -> { DecimalFormat f = new DecimalFormat("#.00"); f.setMultiplier(0); return f.format(-7L) + " " + f.format(-7) + " " + f.format(-7.0); });
    show("infinity product", () -> { DecimalFormat f = new DecimalFormat("#.##"); f.setMultiplier(-2); return f.format(Double.POSITIVE_INFINITY) + " " + f.format(Double.NaN); });
    // `parseObject` is the same read under the name `Format` gave it.
    show("parseObject", () -> new DecimalFormat("#0.00;(#)").parseObject("(12.50)rest"));
    show("parseObject bad", () -> new DecimalFormat("#").parseObject("abc"));
    show("NumberFormat", () -> NumberFormat.getInstance().parse("1,234.5x") + " " + NumberFormat.getPercentInstance().parse("50%"));
    // A negative subpattern that says what the positive one already said is
    // thrown away and the minus sign derived instead — a question about the
    // PATTERN, asked here because it is what tells the two forms apart.
    for (String p : new String[] {"#;#", "#u;#u", "0;#", "#;#0", "a#b;a#b", "$#;$#", "#;(#)", "#;-#"}) {
      final String pp = p;
      show("[" + pp + "] halves", () -> {
        DecimalFormat f = new DecimalFormat(pp);
        return f.toPattern() + " [" + f.getPositivePrefix() + "|" + f.getNegativePrefix() + "]["
            + f.getPositiveSuffix() + "|" + f.getNegativeSuffix() + "] " + f.format(5) + "/" + f.format(-5); });
    }
  }
}
"##
);

differential_test!(
    every_decimal_format_pattern,
    "DF",
    r##"
import java.text.DecimalFormat;
import java.text.NumberFormat;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;
public class DF {
  interface Body { Object get() throws Exception; }
  static void show(String l, Body b) {
    try { System.out.println(l + " = " + b.get()); }
    catch (Throwable e) { System.out.println(l + " ! " + e.getClass().getName() + ": " + e.getMessage()); }
  }
  public static void main(String[] a) {
    String[] patterns = {"0", "0.00", "#.##", "#,##0.00", "#,###", "0.0#", "000", "#", "0%", "0.0%",
                         "$#,##0.00", "#,##0.00 units", "0.###E0", "'#'0", "#.##;(#.##)", "+0;-0", "\u00a4#,##0.00"};
    double[] values = {0, 1, -1, 0.5, 2.5, 3.14159, 1234.5678, -1234.5678, 1000000, 0.0001, -0.5, 1.005, 99.995};
    for (String p : patterns) {
      for (double v : values) {
        final String pp = p; final double vv = v;
        show("[" + pp + "] " + vv, () -> new DecimalFormat(pp).format(vv));
      }
      final String pp = p;
      show("[" + pp + "] toPattern", () -> new DecimalFormat(pp).toPattern());
      show("[" + pp + "] long", () -> new DecimalFormat(pp).format(1234567890123L));
      show("[" + pp + "] BigDecimal", () -> new DecimalFormat(pp).format(new BigDecimal("1234.5678")));
      show("[" + pp + "] BigInteger", () -> new DecimalFormat(pp).format(new BigInteger("12345678901234567890")));
    }
    show("bad pattern", () -> new DecimalFormat("0.0.0"));
    show("empty pattern", () -> new DecimalFormat("").format(1234.5));
    show("default ctor", () -> new DecimalFormat().format(1234.5678) + " | " + new DecimalFormat().toPattern());
    show("getInstance", () -> NumberFormat.getInstance().format(1234.5678));
    show("getNumberInstance", () -> NumberFormat.getNumberInstance().format(1234.5678));
    show("getIntegerInstance", () -> NumberFormat.getIntegerInstance().format(1234.5678) + " " + NumberFormat.getIntegerInstance().format(1234.4));
    show("getCurrencyInstance", () -> NumberFormat.getCurrencyInstance().format(1234.5678) + " " + NumberFormat.getCurrencyInstance().format(-5));
    show("getPercentInstance", () -> NumberFormat.getPercentInstance().format(0.756) + " " + NumberFormat.getPercentInstance().format(1));
    show("setMaximumFractionDigits", () -> { NumberFormat f = NumberFormat.getInstance(); f.setMaximumFractionDigits(2); return f.format(1234.5678); });
    show("setMinimumFractionDigits", () -> { NumberFormat f = NumberFormat.getInstance(); f.setMinimumFractionDigits(3); return f.format(1234.5); });
    show("setGroupingUsed", () -> { NumberFormat f = NumberFormat.getInstance(); f.setGroupingUsed(false); return f.format(1234567.89); });
    show("setMaximumIntegerDigits", () -> { NumberFormat f = NumberFormat.getInstance(); f.setMaximumIntegerDigits(3); return f.format(1234567.89); });
    show("setRoundingMode", () -> { DecimalFormat f = new DecimalFormat("0.0"); f.setRoundingMode(RoundingMode.FLOOR); return f.format(2.55) + " " + f.getRoundingMode(); });
    show("applyPattern", () -> { DecimalFormat f = new DecimalFormat("0"); f.applyPattern("0.000"); return f.format(2.5); });
    show("parse", () -> new DecimalFormat("#,##0.00").parse("1,234.56"));
    show("parse int", () -> new DecimalFormat("0").parse("42"));
    show("parse bad", () -> new DecimalFormat("0").parse("abc"));
    show("parse partial", () -> new DecimalFormat("0").parse("12abc"));
    show("half even default", () -> new DecimalFormat("0.0").format(0.25) + " " + new DecimalFormat("0.0").format(0.35) + " " + new DecimalFormat("0").format(0.5) + " " + new DecimalFormat("0").format(1.5));
    show("getMaximumFractionDigits", () -> { DecimalFormat f = new DecimalFormat("0.00"); return f.getMaximumFractionDigits() + " " + f.getMinimumFractionDigits() + " " + f.getMaximumIntegerDigits() + " " + f.getMinimumIntegerDigits() + " " + f.isGroupingUsed() + " " + f.getGroupingSize(); });
    show("format is NumberFormat", () -> { NumberFormat f = new DecimalFormat("0.00"); return f.format(3.14159); });
    show("toString", () -> new DecimalFormat("0.00").getClass().getName());
    show("equals", () -> new DecimalFormat("0.00").equals(new DecimalFormat("0.00")));
    show("negative zero", () -> new DecimalFormat("0.0").format(-0.001) + " " + new DecimalFormat("0.0").format(-0.0));
  }
}
"##
);

differential_test!(
    a_decimal_format_breaks_a_tie_as_a_jdk_does,
    "DecTies",
    r###"
import java.text.DecimalFormat;

public class DecTies {
    public static void main(String[] args) {
        // A `double` on a tie is the one place a formatter's rounding is not
        // simply HALF_EVEN: which way it goes depends on which side of the
        // shortest decimal the true value fell, on whether the value is a
        // whole number, and on whether `Double.toString` wrote it in
        // scientific notation.
        String[] patterns = {
            "0", "0.0", "0.00", "0.000", "#.##", "#,##0.00", "0.###E0", "#.##E0",
            "##0.##E0", "0%", "0.0%", "#,##0.####",
        };
        double[] values = {
            0, 0.5, 1.5, 2.5, 3.5, 0.05, 0.005, 0.0005, 0.00005, 1.005, 1.0005,
            2.675, 1.115, 8.835, 0.125, 0.375, 99.995, 12345, 12335, 12325, 12355,
            1234.5, 1233.5, 12345000, 0.00012345, 0.15, 0.015, 0.0015, -0.5, -2.675,
            -963.755, 15.005, 30.115, 43.005, -269.3345,
        };
        for (String shape : patterns) {
            DecimalFormat format = new DecimalFormat(shape);
            StringBuilder line = new StringBuilder(shape).append(" |");
            for (double value : values) {
                line.append(' ').append(format.format(value));
            }
            System.out.println(line);
            // ...and the same values as exact decimals, which round the plain
            // half-even way instead.
            StringBuilder exact = new StringBuilder(shape).append(" exact |");
            for (double value : values) {
                exact.append(' ').append(format.format(new java.math.BigDecimal(String.valueOf(value))));
            }
            System.out.println(exact);
        }
    }
}
"###
);

